/* THE HOME (0.17.0): app.myicor.com's Home, `app/(app)/page.tsx`, in the plugin. The page head (the weekday, "Find your
 * way back to clear", where you left off as one line), the newest from Tom and Paco, one place card per product on the
 * roadmap with its progress (INKLINE .ik-placecard, DESIGN §46), then what lives on app.myicor.com only and what lives in
 * this vault. Only what the myICOR MCP serves is drawn as data; the rest is a link, never a guess. */
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
/* The four courses of the ICOR Journey, Input to Refine (myicor-27 lib/journey.ts). */
const JOURNEY_SLUGS = ['digital-note-taking-like-a-pro', 'pkm', 'task-management', 'automation'];
/* The products in the order of the app's menu, with the app's own lines. `slugs`: the courses whose progress is the
 * card's meter; `build`: the meter comes from the Build outline; `note`: what the card says without a meter. */
const HOME_PLACES = [
  { place: 'kickstart', label: 'ICOR Kickstart', path: '/kickstart', line: 'The foundations, free for every member.', slugs: ['kickstart', 'icor-kickstart'], note: 'Your steps are on app.myicor.com' },
  { place: 'journey', label: 'ICOR Journey', path: '/journey', line: 'Your own system: Input, Control, Output, Refine.', slugs: JOURNEY_SLUGS, note: 'Your progress is on app.myicor.com' },
  { place: 'teams', label: 'ICOR Teams', path: '/teams', line: 'The same system, run as a team.', slugs: ['icor-teams'], fallbackSlugs: ['project-management'], note: 'Your progress is on app.myicor.com' },
  { place: 'aynic', label: 'ICOR AI', text: 'AI', path: '/icorai', line: 'Make AI work inside your system.', tag: 'Soon', note: 'Opening soon: 49 lessons in seven modules' },
  { place: 'coaching', label: 'ICOR Coaching', path: '/coaching', line: 'Live with Tom and Paco, every week.', tag: 'Inner Circle', note: 'The next sessions and every recording are on app.myicor.com' },
  { place: 'build', label: 'ICOR Build', path: '/build', line: 'Your own tools, built with AI: in Obsidian, or from scratch.', tag: 'Optional', build: true, note: 'Your build is on app.myicor.com' },
];
/* What only app.myicor.com has for now (the MCP serves none of it): rows that open it there. */
const HOME_ELSEWHERE = [
  { icon: 'at-sign', title: 'Mentions and replies', sub: 'Your inbox', path: '/inbox' },
  { icon: 'calendar', title: 'Coming up', sub: 'The next events and coaching sessions', path: '/events' },
  { icon: 'vote', title: 'This week’s poll', sub: 'Polls', path: '/polls' },
];

/** A course's slug, from its app link (get_courses gives `url`, not the slug). */
function courseSlugOf(c) {
  const m = /\/courses\/([^/?#]+)/.exec(String((c && c.url) || ''));
  return m ? m[1] : String((c && c.slug) || '');
}

/** { done, total } over the required lessons of the courses with these slugs, or null when none is listed. */
function courseProgress(courses, slugs) {
  const list = (courses || []).filter((c) => (slugs || []).includes(courseSlugOf(c)));
  let done = 0, total = 0;
  for (const c of list) {
    const t = Number(c.required_lesson_count) || Number(c.lesson_count) || 0;
    const d = Number(c.completed_required_lessons != null ? c.completed_required_lessons : c.completed_lessons) || 0;
    total += t;
    done += Math.max(0, Math.min(d, t));
  }
  return total ? { done, total } : null;
}

/** { done, total } of the ICOR Build path from get_aynic_course's outline (text): the lesson lines before the lessons
 *  that moved to another journey, "(built)" on the ones the member built. Null when the outline has no lesson lines. */
function buildProgress(text) {
  const src = String(text || '');
  const cut = src.indexOf('\n## Moved to');
  let done = 0, total = 0;
  for (const line of (cut >= 0 ? src.slice(0, cut) : src).split('\n')) {
    if (!/^- \S+ · /.test(line)) continue;
    total += 1;
    if (/ \(built\):/.test(line)) done += 1;
  }
  return total ? { done, total } : null;
}

/** By Tom or Paco (the app's rule: no author reads as theirs). */
function byUs(r) { return /tom|paco/i.test(String((r && r.author) || 'Tom & Paco')); }

/** The newest video, article and podcast by Tom and Paco, in that order, from get_latest_resources (newest first). */
function newestFromUs(resources) {
  const list = (resources || []).filter(byUs);
  const pick = (re) => list.find((r) => re.test(String(r.type || '')));
  return [pick(/video/i), pick(/article/i), pick(/podcast/i)].filter(Boolean);
}

/** The course to pick up: the first journey course not finished, Input to Refine, then ICOR Teams. */
function nextCourse(courses) {
  const order = [...JOURNEY_SLUGS, 'icor-teams'];
  for (const slug of order) {
    const c = (courses || []).find((x) => courseSlugOf(x) === slug);
    if (c && (Number(c.progress_percent) || 0) < 100) return c;
  }
  return null;
}

/** Everything the Home draws, from the fetched data; pure, so the gate can read it. */
function homeModel(data) {
  const d = data || {};
  const courses = (d.courses && d.courses.courses) || [];
  const cards = HOME_PLACES.map((p) => {
    let meter = null;
    if (p.build) meter = buildProgress(d.buildOutline);
    else if (p.slugs) meter = courseProgress(courses, p.slugs) || (p.fallbackSlugs ? courseProgress(courses, p.fallbackSlugs) : null);
    let count = meter ? meter.done + ' of ' + meter.total + (p.build ? ' built' : ' done') : null;
    let frac = meter ? meter.done / meter.total : null;
    /* The journey without its courses listed: the server's own share of the journey. */
    const pct = d.journey && d.journey.journey_complete_percent;
    if (!meter && p.place === 'journey' && typeof pct === 'number' && pct >= 0 && pct <= 100) {
      frac = pct / 100;
      count = Math.round(pct) + '% of the journey';
    }
    return {
      place: p.place, label: p.label, text: p.text || null, line: p.line, tag: p.tag || null,
      url: BASE_URL + p.path, frac, count, note: count ? null : p.note,
    };
  });
  return {
    cards,
    newest: newestFromUs(d.latest && d.latest.resources),
    next: nextCourse(courses),
    elsewhere: HOME_ELSEWHERE.map((e) => ({ icon: e.icon, title: e.title, sub: e.sub, url: BASE_URL + e.path })),
  };
}

/** A date as the app writes it: 20 Nov 2026. */
function shortDate(v) {
  const t = v ? new Date(v) : null;
  return t && !isNaN(t) ? t.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '';
}

/* The six rooms and their dashboards. */
const ROOM_VIEW_TYPE = 'micor-room-dash';
/* A ROOM IS ITS NUMBER. THE WORDS AFTER IT ARE A LABEL.
 *
 * `path` used to be the contract. When `01 INBOX` was renamed `01 Inbox` to
 * match its title-case siblings, the literal here stopped matching in silence:
 * a `data-path` selector that finds nothing throws nothing, so the Inbox simply
 * lost its dashboard button and onboarding pointed at a folder that did not
 * exist. Correcting the literal would leave the same trap armed for the next
 * rename, and there will be one. The same two-character edit cost 27 files and
 * 21 CSS selectors elsewhere.
 *
 * `room` is the identity and it did not move: it is the sort key, and this
 * table's own copy already says so ("ROOM 01 - INBOX"). `path` is now a
 * DECLARATION of the shipped default, resolved against the vault's real folder
 * at load by `resolveRooms()`, so a room may be called anything its owner likes
 * - renamed, translated - and everything downstream keeps working.
 *
 * ICOR for Life 3.0 (0.17.0): work in progress happens in the agent harness,
 * not in the vault, so room 03 is gone and only finished work comes in, as
 * objects. Room 06 is the Outer World: what others made. A vault made before
 * 3.0 has no Outer World, and some still have the retired `06 AI Team`, so
 * the room is `optional` (its absence is not announced) and never binds to a
 * folder named in `retired` (the number alone would claim the old room). */
const ROOMS = [
  { room: '00', path: '00 Daily Scratchpad', key: 'scratchpad', title: 'The Scratchpad.', hand: 'raw thought, stamped later', kicker: 'ROOM 00 · DAILY SCRATCHPAD' },
  { room: '01', path: '01 Inbox', key: 'inbox', title: 'The Inbox.', hand: 'it empties, always', kicker: 'ROOM 01 · INBOX' },
  { room: '04', path: '04 Inner World', key: 'inner', title: 'The Inner World.', hand: 'what you know and live', kicker: 'ROOM 04 · INNER WORLD' },
  { room: '05', path: '05 Assets', key: 'assets', title: 'The Shelves.', hand: 'files your notes lean on', kicker: 'ROOM 05 · ASSETS' },
  { room: '06', path: '06 Outer World', key: 'outer', title: 'The Outer World.', hand: 'what others made', kicker: 'ROOM 06 · OUTER WORLD', optional: true, retired: ['06 AI Team'] },
];

/* The leading room number of a folder name, or null when it carries none. */
function roomNumberOf(name) {
  const m = /^(\d{2})/.exec(String(name));
  return m ? m[1] : null;
}

/** The vault's own name for a room, by number. Null when the vault has no such room. */
function findRoomFolder(vault, number, skip) {
  const root = vault && vault.getRoot ? vault.getRoot() : null;
  const children = (root && root.children) || [];
  for (const child of children) {
    if (child.children === undefined) continue;
    if (skip && skip.includes(child.name)) continue;
    if (roomNumberOf(child.name) === number) return child.name;
  }
  return null;
}

/** The room a vault path sits in, by number. */
function roomOfPath(path) {
  const head = String(path).split('/')[0];
  return roomNumberOf(head);
}

/** The room a stored path names, matched by its number rather than its words. */
function roomFor(path) {
  if (!path) return null;
  const exact = ROOMS.find((r) => r.path === path);
  if (exact) return exact;
  const number = roomOfPath(path);
  return number ? ROOMS.find((r) => r.room === number) || null : null;
}

/* ------------------------------------------------------------------------- *
 * PKCE helpers (Node crypto — desktop only, declared in manifest)
 * ------------------------------------------------------------------------- */

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/* The OAuth consent MUST open in the system browser, never in Obsidian's
 * in-app Web Viewer: Turnstile and the user's existing login session live in
 * the real browser. shell.openExternal bypasses the Web Viewer intercept. */
function openInSystemBrowser(url) {
  /* macOS first tier: the system `open` command via LaunchServices. Electron's
   * shell.openExternal is flaky here — it can foreground the browser without
   * handing over the URL. `open <url>` always delivers. */
  if (typeof process !== 'undefined' && process.platform === 'darwin') {
    try {
      require('child_process').execFile('/usr/bin/open', [url]);
      return true;
    } catch (e) { /* fall through to Electron shell */ }
  }
  try {
    const electron = require('electron');
    const shell = electron.shell || (electron.remote && electron.remote.shell);
    if (shell && shell.openExternal) {
      const r = shell.openExternal(url);
      if (r && r.catch) r.catch(() => { try { window.open(url); } catch (e) { /* fallback below */ } });
      return true;
    }
  } catch (e) { /* fall through to window.open */ }
  try {
    return !!window.open(url);
  } catch (e) {
    return false;
  }
}

function makePkce() {
  const crypto = require('crypto');
  const verifier = b64url(crypto.randomBytes(48));
  const challenge = b64url(crypto.createHash('sha256').update(verifier).digest());
  const state = b64url(crypto.randomBytes(16));
  return { verifier, challenge, state };
}

/* Minimal HTML shown in the browser tab after the OAuth redirect lands. */
function callbackHtml(ok, detail) {
  const title = ok ? 'Connected' : 'Not connected';
  const msg = ok
    ? 'Your vault is now connected to myICOR. You can close this tab and return to Obsidian.'
    : 'The connection was not completed' + (detail ? ' (' + detail + ')' : '') + '. You can close this tab and try again from Obsidian.';
  return '<!doctype html><html><head><meta charset="utf-8"><title>myICOR — ' + title + '</title>' +
    '<style>body{margin:0;display:flex;align-items:center;justify-content:center;min-height:100vh;' +
    'background:#0c0e12;color:#f6f3ec;font:16px/1.6 -apple-system,BlinkMacSystemFont,system-ui,sans-serif}' +
    '.card{max-width:26rem;padding:2.5rem;text-align:center}' +
    'svg{width:96px;color:' + (ok ? '#ff5a2d' : '#8e897d') + '}' +
    'h1{font-size:1.4rem;margin:.75rem 0 .5rem}p{color:#c9c4b8;margin:0}</style></head>' +
    '<body><div class="card">' + MARK_SVG + '<h1>' + title + '</h1><p>' + msg + '</p></div></body></html>';
}

/* ------------------------------------------------------------------------- *
 * Where the keys live (0.15.0)
 *
 * The two OAuth tokens used to sit in plain text in this plugin's data.json.
 * They now live in ONE of two backends, chosen by the `secretsBackend`
 * setting, and data.json keeps only what is not secret (scope, expiry):
 *
 *   'secret-storage'  Obsidian's keychain (Settings, General, Keychain): the
 *                     `app.secretStorage` API of Obsidian 1.11.4 and newer,
 *                     three synchronous methods (setSecret, getSecret,
 *                     listSecrets), ids lowercase alphanumeric with dashes.
 *                     Per device and outside the vault: a key entered on the
 *                     Mac is not on the iPad, and Obsidian Sync does not
 *                     carry it. The store is shared by every plugin, which
 *                     is why every id carries this plugin's prefix.
 *   'env-file'        KEY=value lines in a file inside the vault, default
 *                     `.icor-for-life/.env` (0.17.0): the vault's own
 *                     system folder, one file shared with ICOR for Life -
 *                     Planner and AI Chat. Obsidian does not index a
 *                     folder whose name starts with a dot, so the file is
 *                     read and written through the vault adapter only,
 *                     never the Vault API. Rides with the vault, so a sync
 *                     that carries hidden files takes it along (iCloud
 *                     Drive, git and Dropbox do; Obsidian Sync skips files
 *                     whose name starts with a dot, and the default name
 *                     does). The plugin adds the path to .gitignore the
 *                     way it always did for data.json. The path is
 *                     vault-relative and checked: no absolute path, no
 *                     `..`, so it cannot leave the vault.
 *
 *                     Before 0.17.0 the default was
 *                     `06 AI Team/AI Team Knowledge/.env`, in a room the
 *                     vault no longer has. The old default in data.json
 *                     reads as the new one; while the new file is missing
 *                     and the old one is there, the old one is the file
 *                     read and written (EnvFileBackend's fallback), the
 *                     member is offered a one-time copy to the new place,
 *                     and the old file is never deleted without a click.
 *
 * The default is the keychain when the API exists, else the env file, and
 * the choice is written to data.json the first time this build loads, so a
 * later Obsidian update never flips the backend under a live connection.
 * At runtime the plugin reads the SELECTED backend only: a silent fallback
 * to the other one would hide a misconfiguration behind a working login.
 * The plaintext tokens of an older data.json are moved into the selected
 * backend once, on load, and the fields blanked; nothing ever moves back
 * into data.json. Switching the dropdown moves nothing by itself; the
 * settings tab shows where each key is and offers a "Move to ..." button.
 *
 * `parseEnvFile` and `upsertEnvLine` are pure (gated by test/secrets.test.mjs):
 * the writer rewrites exactly one line, or appends one, and leaves every
 * other byte of the file as it was, comments included. A key that appears
 * twice is read from and written to its FIRST line, so reader and writer
 * agree. Values are taken literally: no quotes are stripped, nothing is
 * interpolated. Blanking a key writes `KEY=` rather than deleting the line;
 * blanking a key the file does not have changes nothing. A value with a
 * line break is refused (thrown), because a second line would be parsed as
 * a second key by this plugin and by every shell that sources the file.
 * ------------------------------------------------------------------------- */

const SECRET_ID_PREFIX = 'icor-for-life-connect-';
const SECRET_FIELDS = {
  access_token: { id: SECRET_ID_PREFIX + 'access-token', env: 'MYICOR_ACCESS_TOKEN', label: 'Access token' },
  refresh_token: { id: SECRET_ID_PREFIX + 'refresh-token', env: 'MYICOR_REFRESH_TOKEN', label: 'Refresh token' },
};
const SECRET_FIELD_NAMES = Object.keys(SECRET_FIELDS);
const SECRETS_BACKENDS = ['secret-storage', 'env-file'];
const DEFAULT_ENV_FILE_PATH = '.icor-for-life/.env';
const LEGACY_ENV_FILE_PATH = '06 AI Team/AI Team Knowledge/.env';
const BACKEND_LABELS = {
  'secret-storage': "Obsidian's keychain",
  'env-file': 'the env file',
};

/* Feature detection: the two methods this layer calls, and nothing else. */
function secretStorageUsable(storage) {
  return !!(storage && typeof storage.getSecret === 'function' && typeof storage.setSecret === 'function');
}

function defaultSecretsBackend(app) {
  return secretStorageUsable(app && app.secretStorage) ? 'secret-storage' : 'env-file';
}

/* The backend that is in use: the choice when it is valid and usable here.
   'secret-storage' on an Obsidian without the API resolves to 'env-file',
   the only choice there. */
function effectiveSecretsBackend(choice, app) {
  if (choice === 'secret-storage' && secretStorageUsable(app && app.secretStorage)) return 'secret-storage';
  return 'env-file';
}

/* The env file path as the member typed it, checked and tidied: slashes
   one way, no empty or `.` segments, and refused when it is absolute, home
   relative or climbs out of the vault with `..`. Same shape as Planner's
   normalizeEnvFilePath; the error sentences carry no value. */
function normalizeEnvFilePath(v) {
  const raw = String(v == null ? '' : v).trim().replace(/\\/g, '/');
  if (!raw) return { ok: false, path: '', error: 'Enter a path inside the vault, for example ' + DEFAULT_ENV_FILE_PATH + '.' };
  if (/^([a-zA-Z]:)?\//.test(raw) || raw.startsWith('~')) return { ok: false, path: '', error: 'The path is relative to the vault root, not an absolute path.' };
  const parts = raw.split('/').filter((p) => p !== '' && p !== '.');
  if (parts.some((p) => p === '..')) return { ok: false, path: '', error: 'The path must stay inside the vault (no "..").' };
  if (!parts.length) return { ok: false, path: '', error: 'Enter a file name, not a folder.' };
  return { ok: true, path: parts.join('/'), error: '' };
}

/* The path data.json names, adopted: checked, and the old default read as
   the new one, because nobody chose it; every earlier build wrote it. */
function adoptEnvFilePath(v) {
  const p = normalizeEnvFilePath(v).path;
  return !p || p === LEGACY_ENV_FILE_PATH ? DEFAULT_ENV_FILE_PATH : p;
}

/* The older file the default path falls back to; '' for a chosen path. */
function legacyEnvFileFor(path) {
  return path === DEFAULT_ENV_FILE_PATH ? LEGACY_ENV_FILE_PATH : '';
}

function envLineEnding(text) {
  return text.indexOf('\r\n') >= 0 ? '\r\n' : '\n';
}

/* One line of an env file: { key, value } or null for a blank line, a
   comment, a line without `=`, or a key outside the shell alphabet. */
function parseEnvLine(line) {
  const raw = line.endsWith('\r') ? line.slice(0, -1) : line;
  if (!raw.trim() || raw.trimStart().startsWith('#')) return null;
  const eq = raw.indexOf('=');
  if (eq < 0) return null;
  const key = raw.slice(0, eq).trim();
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) return null;
  return { key, value: raw.slice(eq + 1).trim() };
}

/** KEY=value lines to a plain object. The first occurrence of a key wins. */
function parseEnvFile(text) {
  const out = Object.create(null);
  for (const line of String(text || '').split('\n')) {
    const kv = parseEnvLine(line);
    if (kv && !(kv.key in out)) out[kv.key] = kv.value;
  }
  return out;
}

/** The text with KEY set to value: the first KEY= line rewritten in place,
 *  or one line appended (after a line ending when the file has none at its
 *  end). Every other byte stays. Applying it twice gives the same text. */
function upsertEnvLine(text, key, value) {
  const src = String(text || '');
  const v = String(value == null ? '' : value);
  if (/[\r\n]/.test(v)) throw new Error('an env value cannot contain a line break');
  const lines = src.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const kv = parseEnvLine(lines[i]);
    if (!kv || kv.key !== key) continue;
    const cr = lines[i].endsWith('\r') ? '\r' : '';
    lines[i] = key + '=' + v + cr;
    return lines.join('\n');
  }
  /* Blanking a key the file never had would only add an empty line. */
  if (!v) return src;
  const eol = envLineEnding(src);
  if (src === '') return key + '=' + v + eol;
  return src + (src.endsWith('\n') ? '' : eol) + key + '=' + v + eol;
}

/* An older data.json's `tokens` split into what stays (scope, expiry) and
   what moves out (the two tokens). null when there is nothing to move. */
function splitPlaintextTokens(tokens) {
  if (!tokens || typeof tokens !== 'object') return null;
  const secrets = {};
  let any = false;
  for (const f of SECRET_FIELD_NAMES) {
    const v = typeof tokens[f] === 'string' ? tokens[f].trim() : '';
    if (!v) continue;
    secrets[f] = v;
    any = true;
  }
  if (!any) return null;
  const meta = {};
  for (const k of Object.keys(tokens)) if (!SECRET_FIELDS[k]) meta[k] = tokens[k];
  return { meta, secrets };
}

/* What data.json may receive: the data with the secret fields stripped out
   of `tokens`. saveSettings writes through here and nothing else, so a
   token cannot reach the file even if a caller left one in `data.tokens`. */
function persistableData(data) {
  const out = Object.assign({}, data || {});
  if (out.tokens && typeof out.tokens === 'object') {
    const meta = {};
    for (const k of Object.keys(out.tokens)) if (!SECRET_FIELDS[k]) meta[k] = out.tokens[k];
    out.tokens = meta;
  }
  return out;
}

/* Both backends read the two token fields as one object ('' for a field
   that is not set) and write any subset of them ('' blanks). Neither logs. */
class KeychainBackend {
  constructor(storage) {
    if (!secretStorageUsable(storage)) throw new Error("Obsidian's keychain needs Obsidian 1.11.4 or newer");
    this.storage = storage;
  }
  get name() { return 'secret-storage'; }
  async read() {
    const out = {};
    for (const f of SECRET_FIELD_NAMES) {
      let v = null;
      try { v = this.storage.getSecret(SECRET_FIELDS[f].id); } catch (e) { v = null; }
      out[f] = typeof v === 'string' ? v.trim() : '';
    }
    return out;
  }
  /* setSecret throws on a bad id and never carries a value in the message.
     A blank clears: through deleteSecret, which is undocumented in
     obsidian.d.ts and feature-detected (it exists in the 1.13.7 bundle, not
     in the API typings), else by writing '' to an entry that exists; an id
     the store does not hold is left unwritten, so a disconnect never
     creates empty entries. */
  async write(values) {
    for (const f of SECRET_FIELD_NAMES) {
      if (!(f in values)) continue;
      const id = SECRET_FIELDS[f].id;
      const v = String(values[f] == null ? '' : values[f]).trim();
      if (v) { this.storage.setSecret(id, v); continue; }
      if (typeof this.storage.deleteSecret === 'function') { this.storage.deleteSecret(id); continue; }
      let cur = null;
      try { cur = this.storage.getSecret(id); } catch (e) { cur = null; }
      if (typeof cur === 'string' && cur !== '') this.storage.setSecret(id, '');
    }
  }
}

/* The env file. `fallback` (0.17.0) is the old default's file: while the
   file at `path` is missing and the fallback is there, the fallback is the
   one read AND written, so a vault set up before the move keeps working and
   no half-empty new file appears beside the full old one. Which file is in
   use is asked again on every read and write, so a copy made meanwhile (by
   this plugin or ICOR for Life - Planner) is followed at once. */
class EnvFileBackend {
  constructor(adapter, path, fallback) {
    this.adapter = adapter;
    this.path = path;
    this.fallback = fallback === undefined ? legacyEnvFileFor(path) : (fallback || '');
    if (this.fallback === this.path) this.fallback = '';
  }
  get name() { return 'env-file'; }
  /* { active, onLegacy, legacyExists }: the file in use and whether it is
     the old one. Never reads a byte of either file. */
  async locate() {
    if (!this.path) return { active: '', onLegacy: false, legacyExists: false };
    const legacyExists = !!this.fallback && !!(await this.adapter.exists(this.fallback));
    const onLegacy = legacyExists && !(await this.adapter.exists(this.path));
    return { active: onLegacy ? this.fallback : this.path, onLegacy, legacyExists };
  }
  /* The folder a new file goes in, made when missing (the adapter's mkdir
     makes every level). */
  async ensureParent(p) {
    const dir = p.indexOf('/') >= 0 ? p.slice(0, p.lastIndexOf('/')) : '';
    if (!dir || typeof this.adapter.mkdir !== 'function') return;
    if (await this.adapter.exists(dir)) return;
    await this.adapter.mkdir(dir);
  }
  async readText() {
    if (!this.path) return null;
    const { active } = await this.locate();
    if (!(await this.adapter.exists(active))) return null;
    return await this.adapter.read(active);
  }
  async read() {
    const env = parseEnvFile((await this.readText()) || '');
    const out = {};
    for (const f of SECRET_FIELD_NAMES) out[f] = env[SECRET_FIELDS[f].env] || '';
    return out;
  }
  async write(values) {
    if (!this.path) throw new Error('no env file path is set');
    const { active } = await this.locate();
    const current = await this.readText();
    let text = current || '';
    let any = false;
    for (const f of SECRET_FIELD_NAMES) {
      if (!(f in values)) continue;
      const v = String(values[f] == null ? '' : values[f]).trim();
      if (v) any = true;
      text = upsertEnvLine(text, SECRET_FIELDS[f].env, v);
    }
    /* Blanking keys in a file that does not exist creates nothing. */
    if (current == null && !any) return;
    if (current == null) await this.ensureParent(active);
    if (text !== current) await this.adapter.write(active, text);
  }
  /* The one-time copy to the new place: the old bytes unchanged, read back
     before they are trusted. The old file stays. 'moved', 'already' (the
     new file exists), 'none' (no old file); throws on a failed copy, with a
     message that carries no value. */
  async adoptLegacy() {
    if (!this.path || !this.fallback) return 'none';
    if (await this.adapter.exists(this.path)) return 'already';
    if (!(await this.adapter.exists(this.fallback))) return 'none';
    const text = await this.adapter.read(this.fallback);
    await this.ensureParent(this.path);
    await this.adapter.write(this.path, text);
    if ((await this.adapter.read(this.path)) !== text) throw new Error('the copy did not read back the same');
    return 'moved';
  }
  /* The old copy to the trash (the system trash, else the vault's .trash),
     only once the new file is there to read. True when it went. */
  async trashLegacy() {
    if (!this.path || !this.fallback) return false;
    if (!(await this.adapter.exists(this.path)) || !(await this.adapter.exists(this.fallback))) return false;
    if (typeof this.adapter.trashSystem === 'function' && (await this.adapter.trashSystem(this.fallback))) return true;
    if (typeof this.adapter.trashLocal === 'function') { await this.adapter.trashLocal(this.fallback); return true; }
    return false;
  }
}

/* The settings tab's one line per key: where a value exists, and which of
   those places is the one in use. Never the value. */
function secretStatusText(where, backend) {
  const places = [];
  if (where['secret-storage']) places.push("Obsidian's keychain");
  if (where['env-file']) places.push('the env file');
  if (where['data-json']) places.push('data.json in plain text (it will move on the next load)');
  const inUse = where[backend] ? '' : ' Not set in ' + BACKEND_LABELS[backend] + ', which is the backend in use.';
  if (!places.length) return 'Not set.';
  return 'Stored in ' + places.join(' and ') + '.' + inUse;
}

/* ------------------------------------------------------------------------- *
 * Plugin
 * ------------------------------------------------------------------------- */

class MyicorConnectPlugin extends Plugin {
  async onload() {
    this.instanceId = Math.floor(performance.now());
    this.data = Object.assign(
      { clientId: null, tokens: null, secretsBackend: null, envFilePath: DEFAULT_ENV_FILE_PATH },
      (await this.loadData()) || {}
    );
    this.tokens = null;
    this.authInFlight = null;

    /* Pins the backend, guards .gitignore, moves an older build's plaintext
       tokens out of data.json, and fills this.tokens from the backend. */
    await this.initSecrets();
    this.addSettingTab(new MyicorConnectSettingTab(this.app, this));

    this.registerView(VIEW_TYPE, (leaf) => new DashboardView(leaf, this));
    this.registerView(ROOM_VIEW_TYPE, (leaf) => new RoomDashboardView(leaf, this));

    /* The thin ribbon is hidden by the scaffold's own snippet, so this
     * plugin registers NO ribbon action: an icon on a hidden surface is
     * not an entry point. Its routes are the top row (gear, attachTopButtons),
     * the folder-tree footer button, and this command. The terminal used to
     * live in that top row too; it is ICOR for Life - Terminal's own toolbar
     * entry now, under the ICOR for Life logo in the left side panel, so it
     * is not this plugin's route to guard any more. The four vault actions
     * below are palette commands for the same reason - see the block after
     * this one. */
    this.addCommand({
      id: 'open-dashboard',
      name: 'Open myICOR dashboard',
      callback: () => this.activateDashboard(),
    });

    /* THE FOUR VAULT ACTIONS THAT USED TO BE TOOLBAR BUTTONS.
     *
     * They were injected into the file explorer's tool-button row while the
     * left ribbon was hidden and that row was where homeless controls went.
     * The row is now reduced to actions that are actually ON the file tree,
     * and none of these four is one: they create notes and canvases and open
     * the graph, which are actions on the VAULT.
     *
     * They become commands rather than rail stops, because the rail is for
     * plugin entry points and these are not entry points into anything. A
     * command is the discoverable home for a vault action anyway, and it is
     * hotkey-bindable for free.
     *
     * All four, and the evenness is the ruling rather than an oversight.
     * Three of them delegate to core plugins that carry their own palette
     * entries, so a wrapper looks redundant - until the core plugin is
     * DISABLED, at which point its command does not exist and the function
     * has no route and no explanation. These wrappers survive that and say
     * which plugin to turn on. Registering three of four would leave the
     * fourth as the odd one out, which is a shape nobody would choose.
     *
     * All four are ALSO toolbar buttons again, by explicit request:
     * `attachToolbarButtons` reinstates them as a second route. Each
     * button drives its command by id, so there is one implementation
     * with two surfaces and no way for them to disagree. */
    const runCore = (id, missing) => {
      if (!this.app.commands.executeCommandById(id)) new Notice('myICOR: ' + missing);
    };
    this.addCommand({
      id: 'new-unique-note',
      /* Named for what it DOES. The retired button said "New note in the
         Daily Scratchpad" while running the core Unique note creator, which
         files wherever that plugin is configured and not necessarily there.
         A label that promises a location the code does not choose is worse
         than a plain one. */
      name: 'New unique note',
      callback: () => runCore('zk-prefixer', 'enable the Unique note creator core plugin to use this.'),
    });
    this.addCommand({
      id: 'open-daily-note',
      name: "Open today's daily note",
      callback: () => runCore('daily-notes', 'enable the Daily notes core plugin to use this.'),
    });
    this.addCommand({
      id: 'open-graph-view',
      name: 'Open graph view',
      callback: () => runCore('graph:open', 'enable the Graph view core plugin to use this.'),
    });
    /* The only one of the four with logic of its own, and the only one that
       had no other route at all before this. Canvases land beside the notes
       they sketch: 00 Daily Scratchpad/YYYY/MM, the date-nested shape the
       scaffold's validator enforces, named YYYY-MM-DD_canvas, with -N on
       collisions. The year and month folders are created on first use;
       createFolder throws on a folder that exists, so each level is checked
       before it is created and the parent is never assumed. */
    this.addCommand({
      id: 'new-scratchpad-canvas',
      name: 'New canvas in the Daily Scratchpad',
      callback: async () => {
        const d = new Date();
        const pad = (n) => String(n).padStart(2, '0');
        const year = String(d.getFullYear());
        const month = pad(d.getMonth() + 1);
        const folder = '00 Daily Scratchpad/' + year + '/' + month;
        const base = folder + '/' + year + '-' + month + '-' + pad(d.getDate()) + '_canvas';
        let path = base + '.canvas';
        let i = 1;
        while (this.app.vault.getAbstractFileByPath(path)) path = base + '-' + i++ + '.canvas';
        try {
          for (const dir of ['00 Daily Scratchpad/' + year, folder]) {
            if (!this.app.vault.getAbstractFileByPath(dir)) await this.app.vault.createFolder(dir);
          }
          const file = await this.app.vault.create(path, '{"nodes":[],"edges":[]}');
          await this.app.workspace.getLeaf(true).openFile(file);
        } catch (e) {
          new Notice('myICOR: could not create the canvas: ' + e.message);
        }
      },
    });
    /* The conditional control's discovery route. `checkCallback` rather than
     * `callback`, so the command is absent from the palette in exactly the
     * state the button is absent from the slot: one condition, two surfaces,
     * and no way for them to disagree. */
    this.addCommand({
      id: 'collapse-all-folders',
      name: 'Collapse all folders',
      checkCallback: (checking) => {
        const btn = this.collapseAllButton();
        if (!btn) return false;
        if (!checking) btn.click();
        return true;
      },
    });
    this.addCommand({
      id: 'connect',
      name: 'Connect to myICOR',
      callback: () => this.connect().catch((e) => new Notice('myICOR: ' + e.message)),
    });
    this.addCommand({
      id: 'sync-reflections',
      name: 'Sync myICOR reflections into Inner World',
      callback: async () => {
        try {
          const r = await this.syncReflections();
          new Notice('myICOR: ' + r.lastCreated + ' new reflection' + (r.lastCreated === 1 ? '' : 's') + ' synced.');
        } catch (e) {
          new Notice('myICOR: sync failed: ' + e.message);
        }
      },
    });

    /* Folder-tree button: attach once the layout exists, re-attach whenever
     * the file explorer leaf is rebuilt. */
    this.app.workspace.onLayoutReady(() => {
      this.resolveRooms();
      this.sweepRetiredRail();
      this.attachExplorerButton();
      this.attachBanner();
      this.attachRoomButtons();
      this.syncCollapseSlot();
      /* the explorer re-renders folder rows on collapse/expand and vault
       * changes; keep the room buttons present without leaking observers */
      const explorer = document.querySelector('.workspace-leaf-content[data-type="file-explorer"]');
      if (explorer && !this.roomObserver) {
        this.roomObserver = new MutationObserver(() => {
          /* The slot is synced UNDEBOUNCED and the room buttons are not.
             Collapsing a room is a direct result of a click, so a quarter
             second of lag between the click and the control reacting reads as
             the control being broken. Re-attaching room buttons is repair work
             nobody is watching, so it keeps its debounce. */
          this.syncCollapseSlot();
          window.clearTimeout(this.roomObserverTimer);
          this.roomObserverTimer = window.setTimeout(() => this.attachRoomButtons(), 250);
        });
        this.roomObserver.observe(explorer, { childList: true, subtree: true });
      }
    });
    this.registerEvent(this.app.workspace.on('layout-change', () => {
      this.attachExplorerButton();
      this.attachBanner();
      this.syncCollapseSlot();
    }));
  }

  onunload() {
    if (this.explorerButtonEl) this.explorerButtonEl.remove();
    if (this.bannerEl) this.bannerEl.remove();
    if (this.roomObserver) this.roomObserver.disconnect();
    /* The slot classes are ours and the container is Obsidian's, so they come
       off on the way out. Left behind they would outlive the CSS that reads
       them and hide a control the host still owns. */
    for (const row of document.querySelectorAll('.micor-tree-slot')) {
      row.classList.remove('micor-tree-slot', 'micor-can-collapse');
    }
    /* Every class here but the last is LIVE - room buttons, top buttons,
       and the four vault-action buttons back on the explorer toolbar - and
       their nodes come off on the way out like anything else this plugin
       owns. Only `.micor-toolbar-extra` is RETIRED: it was the shared class
       of the old canvas and graph buttons, which came back under their own
       classes, so nothing creates it any more. Its sweep outlives the code
       that made it on purpose, because an in-place upgrade from a build
       that still injected it leaves the nodes behind with nothing left to
       take them out. */
    for (const el of document.querySelectorAll('.micor-room-btn, .micor-top-btn, .micor-unique-note, .micor-daily-note, .micor-new-canvas, .micor-graph-view, .micor-banner, .micor-toolbar-extra')) el.remove();
    this.sweepRetiredRail();
    this.closeAuthServer();
  }

  /* THE RETIRED LEFT-RAIL NODES.
   *
   * The rail grouped Obsidian's ribbon actions into two containers behind a
   * fold. It is gone: the ribbon is hidden again and every entry point it
   * carried is back on a surface the user can see. Nothing in this build
   * creates these nodes, and an in-place upgrade from the rail build is the
   * only way they can exist - which is exactly why the sweep has to outlive
   * the code that made them, and why it runs at LOAD as well as at unload.
   * At unload alone it would only ever clean up after itself.
   *
   * The order is the whole rule. `.micor-rail-behind` holds OBSIDIAN'S OWN
   * ribbon actions, so its children go back into the host's container BEFORE
   * the container is removed. This sweep may never be the reason another
   * plugin's icon is missing. */
  sweepRetiredRail() {
    for (const behind of document.querySelectorAll('.micor-rail-behind')) {
      const host = behind.parentElement;
      if (!host) continue;
      for (const el of Array.from(behind.children)) host.appendChild(el);
    }
    for (const el of document.querySelectorAll('.micor-rail-fold, .micor-rail-behind, .micor-rail-vault, .micor-rail-mark')) el.remove();
    /* The body class, not the dashboard's own `.micor-rail` path element:
       only the rail build ever put this on <body>. */
    document.body.classList.remove('micor-rail');
  }

  async saveSettings() {
    /* The strip is the guard that keeps a token out of data.json. The one
       state it must not run in: an older build's tokens that the backend
       refused to take on load. Stripping them would lose the connection
       instead of moving it, so they stay, the Notice said so, and the next
       load tries again. */
    await this.saveData(this.secretsUnmoved ? this.data : persistableData(this.data));
  }

  /* --------------------------------------------------- where the keys live */

  /* What the setting says, defaulted; and what is actually in use here. */
  secretsBackendChoice() {
    return SECRETS_BACKENDS.includes(this.data.secretsBackend) ? this.data.secretsBackend : defaultSecretsBackend(this.app);
  }
  secretsBackend() {
    return effectiveSecretsBackend(this.secretsBackendChoice(), this.app);
  }
  /* The path in use: the setting when it passes the check, else the
     default. A stored value that fails the check never reaches the disk,
     and the old default reads as the new one (adoptEnvFilePath). */
  envFilePath() {
    return adoptEnvFilePath(this.data.envFilePath);
  }
  secretsBackendFor(name) {
    if (name === 'secret-storage') return new KeychainBackend(this.app.secretStorage);
    return new EnvFileBackend(this.app.vault.adapter, this.envFilePath());
  }
  secretsStore() {
    return this.secretsBackendFor(this.secretsBackend());
  }

  /* Runs once per load, after loadData and before anything reads a token.
     Order matters: the choice is pinned first so the .gitignore guard knows
     which file to cover, the guard runs before the migration can write a
     token anywhere, and the in-memory tokens are read last, from the
     backend that is in use and nowhere else. */
  async initSecrets() {
    let changed = false;
    if (!SECRETS_BACKENDS.includes(this.data.secretsBackend)) {
      this.data.secretsBackend = defaultSecretsBackend(this.app);
      changed = true;
    }
    const envPath = adoptEnvFilePath(this.data.envFilePath);
    if (this.data.envFilePath !== envPath) {
      this.data.envFilePath = envPath;
      changed = true;
    }
    await this.ensureGitignore();
    /* 0.17.0: a vault whose keys are still in the old file (room 06) is
       asked once whether to copy it to the new place. The flag is saved
       below before the question is shown, so it is never asked twice. */
    let offerMove = false;
    if (this.secretsBackend() === 'env-file' && this.data.envMoveOffered !== true) {
      let at = null;
      try { at = await this.secretsStore().locate(); } catch { at = null; }
      if (at && at.onLegacy) {
        this.data.envMoveOffered = true;
        offerMove = true;
        changed = true;
      }
    }
    const plain = splitPlaintextTokens(this.data.tokens);
    this.secretsUnmoved = false;
    if (plain) {
      try {
        await this.secretsStore().write(plain.secrets);
        this.data.tokens = plain.meta;
        changed = true;
      } catch (e) {
        this.secretsUnmoved = true;
        /* The backend refused, so the tokens stay where they were until it
           accepts them; blanking first would lose the connection. The
           sentence names the backend, never a value. */
        new Notice('myICOR: could not move the keys into ' + BACKEND_LABELS[this.secretsBackend()] + '. They stay in data.json until the next load.', 12000);
      }
    }
    if (changed) await this.saveSettings();
    await this.loadTokens();
    if (offerMove) this.offerEnvFileMove();
  }

  /* ---- the env file's move out of room 06 (0.17.0) ----
     Asked once at load, and on offer in the settings tab while the old
     file is the one in use. Every sentence names paths only. */
  offerEnvFileMove() {
    const text = 'myICOR: your keys are still read from the old file at ' + LEGACY_ENV_FILE_PATH + '. Their new place is ' + DEFAULT_ENV_FILE_PATH + '.';
    if (typeof createFragment !== 'function') {
      new Notice(text + ' The ICOR for Life - Connect settings have a button to copy them there.', 30000);
      return;
    }
    const frag = createFragment((f) => {
      f.createDiv({ text });
      const b = f.createEl('button', { text: 'Copy them there' });
      b.addEventListener('click', () => { this.moveEnvFileFromLegacy(); });
    });
    new Notice(frag, 30000);
  }

  /* Copy the old file to the default place and read it from there. The old
     file stays; the Notice says where. */
  async moveEnvFileFromLegacy() {
    const store = this.secretsBackendFor('env-file');
    let r = 'failed';
    try { r = await store.adoptLegacy(); } catch { r = 'failed'; }
    if (r === 'moved') {
      await this.ensureGitignore();
      await this.loadTokens();
      this.refreshExplorerDot();
      new Notice('myICOR: copied your keys file to ' + store.path + ' and reads it from there now. The old file is still at ' + store.fallback + '; the ICOR for Life - Connect settings can put it in the trash once nothing else reads it.', 15000);
    } else if (r === 'already') new Notice('myICOR: ' + store.path + ' is already there and is the file in use.');
    else if (r === 'none') new Notice('myICOR: there is no old keys file to copy.');
    else new Notice('myICOR: the keys file could not be copied to ' + store.path + '. Nothing was removed; the old file is still in use.', 12000);
    return r;
  }

  async trashLegacyEnvFile() {
    const store = this.secretsBackendFor('env-file');
    let gone = false;
    try { gone = await store.trashLegacy(); } catch { gone = false; }
    new Notice(gone ? 'myICOR: moved the old keys file at ' + store.fallback + ' to the trash.' : 'myICOR: the old keys file at ' + store.fallback + ' was not moved to the trash.');
    return gone;
  }

  /* this.tokens from the selected backend plus data.json's scope and expiry.
     No refresh token, no connection: an access token alone cannot renew. */
  async loadTokens() {
    const meta = this.data.tokens && typeof this.data.tokens === 'object' ? this.data.tokens : {};
    let secrets = null;
    try { secrets = await this.secretsStore().read(); } catch (e) { secrets = null; }
    if (!secrets || !secrets.refresh_token) {
      this.tokens = null;
      return;
    }
    this.tokens = {
      access_token: secrets.access_token || '',
      refresh_token: secrets.refresh_token,
      scope: meta.scope || OAUTH_SCOPE,
      expires_at: Number(meta.expires_at) || 0,
    };
  }

  /* Persist the in-memory tokens: the two secrets to the backend, the rest
     to data.json. The only writer of a token after load. */
  async saveTokens() {
    const t = this.tokens;
    await this.secretsStore().write({
      access_token: t ? t.access_token : '',
      refresh_token: t ? t.refresh_token : '',
    });
    this.data.tokens = t ? { scope: t.scope, expires_at: t.expires_at } : null;
    await this.saveSettings();
  }

  /* A key pasted into the settings tab. The expiry is reset so the first
     call refreshes, which is also what proves a pasted refresh token. */
  async setSecretByHand(field, value) {
    const v = String(value == null ? '' : value).trim();
    if (!SECRET_FIELDS[field] || !v) return false;
    await this.secretsStore().write({ [field]: v });
    this.data.tokens = { scope: OAUTH_SCOPE, expires_at: 0 };
    await this.saveSettings();
    await this.loadTokens();
    this.refreshExplorerDot();
    return true;
  }

  /* Copy one key into `to`, then blank it where it came from. The copy
     lands first, so a refusal on either side never loses the key. */
  async moveSecret(field, to) {
    if (!SECRET_FIELDS[field] || !SECRETS_BACKENDS.includes(to)) return false;
    const from = to === 'secret-storage' ? 'env-file' : 'secret-storage';
    const src = this.secretsBackendFor(from);
    const dst = this.secretsBackendFor(to);
    const v = (await src.read())[field];
    if (!v) return false;
    await dst.write({ [field]: v });
    await src.write({ [field]: '' });
    await this.loadTokens();
    this.refreshExplorerDot();
    return true;
  }

  /* For each key: in which places a value exists. Presence only. */
  async secretLocations() {
    const read = async (name) => {
      try { return await this.secretsBackendFor(name).read(); } catch (e) { return null; }
    };
    const inStore = await read('secret-storage');
    const inEnv = await read('env-file');
    const plain = splitPlaintextTokens(this.data.tokens);
    const out = {};
    for (const f of SECRET_FIELD_NAMES) {
      out[f] = {
        'secret-storage': !!(inStore && inStore[f]),
        'env-file': !!(inEnv && inEnv[f]),
        'data-json': !!(plain && plain.secrets[f]),
      };
    }
    return out;
  }

  /* ---------------------------------------------------------------- views */

  async activateDashboard(page) {
    const existing = this.app.workspace.getLeavesOfType(VIEW_TYPE);
    let leaf;
    if (existing.length > 0) {
      leaf = existing[0];
    } else {
      leaf = this.app.workspace.getLeaf(true);
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    this.app.workspace.revealLeaf(leaf);
    if (page && leaf.view && leaf.view.setPage) leaf.view.setPage(page);
  }

  /* ------------------------------------------------- folder tree button -- */

  /* ---------------------------------------------------------------- *
   * THE FILE-TREE HEADER SLOT
   *
   * The toolbar row under the banner is reduced to the controls that are
   * actually file-tree actions. Two survive: "change sort order", which is
   * permanent because Obsidian registers no command for it and that button is
   * its ONLY route (measured against the app bundle: eight file-explorer
   * command ids, none of them sort), and "collapse all", which is made
   * CONDITIONAL because it is only ever worth a click when more than one room
   * is open.
   *
   * The slot is Obsidian's own `.nav-buttons-container`. We do not build one
   * beside it: the collapse-all button is already the right glyph with the
   * right accessible name and a working handler, so making it conditional is a
   * class toggle rather than a reimplementation.
   *
   * THE CLASS GOES ON THE CONTAINER, NEVER ON THE BUTTON. Obsidian re-creates
   * those buttons on its own schedule, so a class on the button is lost on the
   * next re-render and has to be chased; a class on the container is inherited
   * by whatever the host puts inside it.
   * ---------------------------------------------------------------- */

  /* How many TOP-LEVEL rooms are open.
   *
   * Top-level only, and depth is never counted. The condition has to have the
   * same shape as the effect: collapse-all collapses to the roots, so a count
   * taken at any other depth produces a control that can be offered when its
   * click would do nothing, or withheld when its click would do a lot. It also
   * means drilling in and out inside one room never crosses the threshold, so
   * the control does not twitch while somebody is working. */
  unfoldedRootCount() {
    const container = document.querySelector('.nav-files-container');
    if (!container) return 0;
    const rootChildren =
      container.querySelector('.nav-folder.mod-root > .nav-folder-children')
      || container.querySelector(':scope > .nav-folder-children');
    if (!rootChildren) return 0;
    let open = 0;
    for (const child of rootChildren.children) {
      if (!child.classList.contains('nav-folder')) continue;
      if (!child.classList.contains('is-collapsed')) open += 1;
    }
    return open;
  }

  /* Threshold is 2. One open room is collapsed with one click on the room
   * itself, and a second control for that is a marking on a one. */
  syncCollapseSlot() {
    const row = document.querySelector(
      '.workspace-leaf-content[data-type="file-explorer"] .nav-buttons-container');
    if (!row) return;
    row.classList.add('micor-tree-slot');
    row.classList.toggle('micor-can-collapse', this.unfoldedRootCount() >= 2);
  }

  /* The discovery affordance, and it is a command rather than a tooltip.
   * A first-run hint would fire in the instant the user just opened a second
   * room, which is the instant they are doing something else. The command
   * palette is where an Obsidian user looks for a function they suspect
   * exists, and it makes the function hotkey-bindable for free.
   *
   * It drives Obsidian's OWN button rather than reimplementing the collapse:
   * one implementation, and the glyph the command names is the glyph that
   * moves. `chevrons-down-up` is the collapse direction; when the tree is
   * already collapsed the host swaps in `chevrons-up-down` and the command
   * correctly reports that it has nothing to do. */
  collapseAllButton() {
    const row = document.querySelector(
      '.workspace-leaf-content[data-type="file-explorer"] .nav-buttons-container');
    if (!row) return null;
    for (const btn of row.querySelectorAll('.clickable-icon')) {
      if (btn.querySelector('svg.lucide-chevrons-down-up')) return btn;
    }
    return null;
  }

  /* THE BANNER, WHICH THE THEME ALREADY DRAWS.
   *
   * INKLINE paints the ICOR for Life banner over the folder tree as a
   * `::before` on `.nav-header`, and it looks right with no plugin at all.
   * What it cannot be is CLICKABLE: a theme is CSS, and CSS has no way to
   * make a pseudo-element navigate anywhere.
   *
   * So this injects the one thing only the DOM can provide - a real anchor -
   * and the theme takes it from there. The handover is the class name
   * `micor-banner` and nothing else: INKLINE styles `a.micor-banner` with the
   * same artwork at the same geometry, and stands its painted copy down with
   * `:has(a.micor-banner)`. THE ARTWORK IS NOT HERE. It lives once, in the
   * theme, and a copy in this plugin would be the copy that goes stale.
   *
   * Which means the honest failure mode is worth naming: with a theme that
   * does not know this class, the anchor renders as an empty 4:1 box. It is
   * created only when the header carries INKLINE's own painted banner, which
   * is how it tells that the theme on the other side of the handover is the
   * one holding up its end.
   *
   * Rebuild rather than early-return, for the reason attachExplorerButton
   * gives: an anchor left by an earlier instance keeps its old handler. */
  attachBanner() {
    const header = document.querySelector(
      '.workspace-leaf-content[data-type="file-explorer"] .nav-header');
    if (!header) return;

    const stale = header.querySelector('a.micor-banner');
    if (stale) {
      if (stale.dataset.micorVersion === this.manifest.version
        && stale.dataset.micorInstance === String(this.instanceId)) return;
      stale.remove();
    }

    /* Does the active theme paint a banner here? Read the pseudo-element the
       theme would have drawn, with the anchor absent, and look for an image.
       A theme with no opinion about `.nav-header::before` reports `none` and
       gets no anchor - so this never leaves an empty box on a theme that was
       not built for it. */
    const painted = window.getComputedStyle(header, '::before');
    if (!painted || painted.backgroundImage === 'none' || painted.content === 'none') return;

    const link = header.createEl('a', { cls: 'micor-banner' });
    header.prepend(link);
    link.dataset.micorVersion = this.manifest.version;
    link.dataset.micorInstance = String(this.instanceId);
    /* setAttribute rather than createEl's `href` option: that option has not
       been supported uniformly across the Obsidian API versions this plugin
       runs on, and an anchor with no href is not a link at all - no pointer,
       no keyboard focus, nothing in the status bar on hover. */
    link.setAttribute('href', SITE_URL);
    link.setAttribute('aria-label', 'ICOR for Life - myicor.com');
    link.setAttribute('rel', 'noopener noreferrer');

    /* Handled rather than left to the host: an href alone behaves differently
       across Obsidian's desktop and mobile shells, and a banner that opens a
       page INSIDE the vault window is a trap the user has to find their way
       out of. */
    link.addEventListener('click', (evt) => {
      evt.preventDefault();
      window.open(SITE_URL, '_blank');
    });

    this.bannerEl = link;
  }

  attachExplorerButton() {
    const explorer = document.querySelector('.workspace-leaf-content[data-type="file-explorer"]');
    if (!explorer) return;

    /* Rebuild instead of early-return: a footer left behind by an earlier
     * plugin instance would keep its OLD click handler forever. */
    const stale = explorer.querySelector('.micor-explorer-footer');
    const wasOpen = stale ? stale.classList.contains('is-open') : false;
    if (stale) {
      if (stale.dataset.micorVersion === this.manifest.version && stale.dataset.micorInstance === String(this.instanceId)) return;
      stale.remove();
    }

    const footer = explorer.createDiv({ cls: 'micor-explorer-footer' });
    footer.dataset.micorVersion = this.manifest.version;
    footer.dataset.micorInstance = String(this.instanceId);
    if (wasOpen) footer.classList.add('is-open');

    /* The nav sits ABOVE the button and unfolds upward when connected. */
    const nav = footer.createDiv({ cls: 'micor-nav' });
    const navInner = nav.createDiv({ cls: 'micor-nav-inner' });
    for (const page of PAGES) {
      const item = navInner.createDiv({ cls: 'micor-nav-item' });
      setIcon(item.createDiv({ cls: 'micor-nav-icon' }), page.icon);
      item.createSpan({ text: page.label });
      item.addEventListener('click', () => {
        footer.classList.remove('is-open');
        this.activateDashboard(page.key);
      });
    }

    const btn = footer.createDiv({ cls: 'micor-explorer-button' });
    const mark = btn.createDiv({ cls: 'micor-explorer-mark' });
    mark.innerHTML = MARK_SVG;
    btn.createSpan({ cls: 'micor-explorer-label', text: 'myICOR' });
    const chevron = btn.createDiv({ cls: 'micor-explorer-chevron' });
    setIcon(chevron, 'chevron-up');
    const status = btn.createDiv({ cls: 'micor-explorer-dot' });
    if (this.isConnected()) status.addClass('is-connected');
    btn.setAttribute('aria-label', 'myICOR');
    btn.addEventListener('click', () => {
      /* Not connected: straight to the connect screen. Connected: the
       * button is the fold/unfold toggle for the nav. */
      if (!this.isConnected()) {
        this.activateDashboard();
        return;
      }
      const open = footer.classList.toggle('is-open');
      btn.setAttribute('aria-expanded', String(open));
    });

    this.explorerButtonEl = footer;
  }

  /* The explorer toolbar's four vault-action buttons: today's daily note,
   * the unique-note creator, a new scratchpad canvas, and the graph view,
   * in that order at the start of the row, ahead of the host's file-tree
   * survivors. Reinstated by explicit request after a round as palette-only
   * commands. The commands STAY: each button drives its command by id, so
   * there is one implementation with two surfaces, and the command's own
   * Notice still names the core plugin to enable when that plugin is off.
   *
   * The canvas and graph buttons carry their own classes now. The old
   * build gave both one shared class, and that class stays on the RETIRED
   * sweep list below to clean up in-place upgrades from that build; a
   * class cannot be both swept as retired and created as live, so the
   * revived pair could not inherit it.
   *
   * This runs from the attach pass the explorer observer re-triggers, so
   * the guard below is load-bearing: when the buttons are already present
   * it must return WITHOUT touching the DOM. A callback that mutates
   * unconditionally under a MutationObserver feeds itself; that runaway has
   * blanked this window once already. */
  attachToolbarButtons() {
    const bar = document.querySelector('.workspace-leaf-content[data-type="file-explorer"] .nav-buttons-container');
    if (!bar || bar.querySelector('.micor-unique-note')) return;

    const runOwn = (suffix) => this.app.commands.executeCommandById(this.manifest.id + ':' + suffix);

    const unique = createDiv({ cls: 'clickable-icon nav-action-button micor-unique-note', attr: { 'aria-label': 'New unique note' } });
    setIcon(unique, 'file-clock');
    unique.addEventListener('click', () => runOwn('new-unique-note'));

    const daily = createDiv({ cls: 'clickable-icon nav-action-button micor-daily-note', attr: { 'aria-label': "Open today's daily note" } });
    setIcon(daily, 'calendar-check');
    daily.addEventListener('click', () => runOwn('open-daily-note'));

    const canvas = createDiv({ cls: 'clickable-icon nav-action-button micor-new-canvas', attr: { 'aria-label': 'New canvas in the Daily Scratchpad' } });
    setIcon(canvas, 'layout-dashboard');
    canvas.addEventListener('click', () => runOwn('new-scratchpad-canvas'));

    const graph = createDiv({ cls: 'clickable-icon nav-action-button micor-graph-view', attr: { 'aria-label': 'Open graph view' } });
    setIcon(graph, 'git-fork');
    graph.addEventListener('click', () => runOwn('open-graph-view'));

    /* Daily leftmost, then unique, canvas, graph: the order the row used
     * to read. The theme assigns flex order only to sort and collapse and
     * leaves zero for the rest, so plain insertion at the front is
     * placement enough. */
    bar.insertBefore(graph, bar.firstChild);
    bar.insertBefore(canvas, graph);
    bar.insertBefore(unique, canvas);
    bar.insertBefore(daily, unique);
  }

  /* The settings gear lives alone in the right sidebar's top row now
   * (the left header stays stock - injecting there raced Obsidian's own
   * sidebar toggle and shuffled the order on collapse/reopen). This row
   * used to also carry a terminal shortcut wired to the retired
   * third-party Terminal plugin; the terminal is ICOR for Life - Terminal
   * now, launched from its own toolbar entry under the ICOR for Life logo
   * in the left side panel, so this method does not touch it any more. */
  attachTopButtons() {
    const right = document.querySelector('.workspace-split.mod-right-split .workspace-tab-header-container');
    if (!right || right.querySelector('.micor-top-settings')) return;

    const gear = createDiv({ cls: 'clickable-icon micor-top-btn micor-top-settings', attr: { 'aria-label': 'Settings' } });
    setIcon(gear, 'settings');
    gear.addEventListener('click', () => this.app.setting.open());

    right.appendChild(gear);
  }

  /* Bind every room to the folder the vault ACTUALLY has for its number, and
   * say so out loud when one is missing.
   *
   * The failure this closes is not a crash, it is a shrug: a `data-path`
   * selector that matches nothing throws nothing, so a renamed room lost its
   * dashboard button and its onboarding entry without a single line in the
   * console, and the plugin just quietly did less. A contract keyed on a value
   * somebody else can change has to announce it when it breaks. Said once, at
   * load, and never again. */
  resolveRooms() {
    const missing = [];
    for (const room of ROOMS) {
      const found = findRoomFolder(this.app.vault, room.room, room.retired);
      if (found) room.path = found;
      else if (!room.optional) missing.push(room.room);
    }
    /* A vault with no numbered rooms at all is not a scaffold, and telling
     * somebody their plain vault is broken would be the louder wrong answer. */
    if (missing.length === ROOMS.filter((r) => !r.optional).length) return;
    if (missing.length === 0) return;
    const message = 'ICOR for Life - Connect: this vault has no room ' + missing.join(', ')
      + '. Those dashboards and their folder buttons are unavailable until the rooms are there.';
    console.warn(message);
    new Notice(message, 12000);
  }

  /** Where synced reflections land, under room 04's real folder. */
  reflectionsDir() {
    const room = ROOMS.find((r) => r.room === REFLECTIONS_ROOM);
    const base = (room && room.path) || findRoomFolder(this.app.vault, REFLECTIONS_ROOM);
    if (!base) throw new Error('this vault has no room ' + REFLECTIONS_ROOM + ', so there is nowhere to sync reflections into');
    return base + '/' + REFLECTIONS_SUBDIR;
  }

  attachRoomButtons() {
    this.attachToolbarButtons();
    this.attachTopButtons();
    for (const room of ROOMS) {
      const title = document.querySelector('.nav-folder-title[data-path="' + room.path + '"]');
      if (!title || title.querySelector('.micor-room-btn')) continue;
      const btn = title.createDiv({ cls: 'micor-room-btn', attr: { 'aria-label': room.path + ' dashboard' } });
      setIcon(btn, 'gauge');
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        ev.preventDefault();
        this.openRoomDashboard(room.path);
      });
    }
  }

  async openRoomDashboard(roomPath) {
    const existing = this.app.workspace.getLeavesOfType(ROOM_VIEW_TYPE);
    const leaf = existing.length ? existing[0] : this.app.workspace.getLeaf(true);
    await leaf.setViewState({ type: ROOM_VIEW_TYPE, active: true, state: { room: roomPath } });
    this.app.workspace.revealLeaf(leaf);
  }


  refreshExplorerDot() {
    /* Cosmetic only — must never mask a real error on the auth path. */
    try {
      const dot = document.querySelector('.micor-explorer-dot');
      if (dot) dot.toggleClass('is-connected', this.isConnected());
    } catch (e) { /* no DOM (tests) or dot not mounted: nothing to update */ }
  }

  /* ------------------------------------------------------------- oauth --- */

  isConnected() {
    return !!(this.tokens && this.tokens.refresh_token);
  }

  closeAuthServer() {
    if (this.authServer) {
      try { this.authServer.close(); } catch (e) { /* already closed */ }
      this.authServer = null;
    }
    if (this.authTimer) {
      clearTimeout(this.authTimer);
      this.authTimer = null;
    }
  }

  /* Full connect flow: loopback server -> dynamic registration -> browser
   * consent -> code exchange -> persist tokens -> wire Claude. */
  async connect() {
    if (this.authInFlight) return this.authInFlight;
    this.authInFlight = this.doConnect().finally(() => {
      this.authInFlight = null;
      this.lastAuthUrl = null;
      this.closeAuthServer();
    });
    return this.authInFlight;
  }

  async doConnect() {
    /* The loopback callback server and PKCE need node http/crypto, which the
     * mobile webview does not have. Whether one desktop connect covers every
     * device depends on where the keys live: the env file rides with the
     * vault, Obsidian's keychain stays on the device it was written on, so
     * the sentence names the way out rather than promising a sync.
     *
     * The check is the first statement, before any require: that is the
     * guard shape the community directory's scanner recognises for a plugin
     * that keeps isDesktopOnly false (same shape as Planner's imapConnect).
     * A try/catch around the require does not read as a guard to it. */
    if (!Platform.isDesktopApp) {
      new Notice(
        this.secretsBackend() === 'env-file'
          ? 'Connecting needs the desktop app once. With the env file as the backend the connection follows the vault when your sync carries hidden files (iCloud Drive, git and Dropbox do; Obsidian Sync skips files whose name starts with a dot). With Obsidian Sync, paste the refresh token into the settings tab on this device.'
          : "Connecting needs the desktop app, and with Obsidian's keychain as the backend the connection stays on the device where you connect. Switch to the env file in the settings to share one connection through the vault.",
        12000
      );
      throw new Error('connecting requires the desktop app');
    }
    const http = require('http');
    require('crypto');
    const pkce = makePkce();

    const codePromise = new Promise((resolve, reject) => {
      this.authServer = http.createServer((req, res) => {
        const url = new URL(req.url, 'http://127.0.0.1');
        if (url.pathname !== '/callback') {
          res.writeHead(404).end();
          return;
        }
        const err = url.searchParams.get('error');
        const code = url.searchParams.get('code');
        const state = url.searchParams.get('state');
        const ok = !err && code && state === pkce.state;
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(callbackHtml(!!ok, err || (state !== pkce.state ? 'state mismatch' : '')));
        if (ok) resolve(code);
        else reject(new Error(err === 'access_denied' ? 'access was denied in the browser' : (err || 'state mismatch')));
      });
      this.authServer.on('error', reject);
      this.authTimer = setTimeout(
        () => reject(new Error('timed out waiting for the browser login (5 minutes)')),
        AUTH_TIMEOUT_MS
      );
    });

    await new Promise((resolve, reject) => {
      this.authServer.listen(0, '127.0.0.1', resolve);
      this.authServer.on('error', reject);
    });
    const port = this.authServer.address().port;
    const redirectUri = 'http://127.0.0.1:' + port + '/callback';

    /* Dynamic client registration (RFC 7591; stateless on the server, PKCE
     * carries the security). Registered fresh per connect so the redirect
     * port always matches. */
    const reg = await requestUrl({
      url: REGISTER_URL,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        client_name: 'ICOR for Life Scaffold (Obsidian)',
        redirect_uris: [redirectUri],
        grant_types: ['authorization_code', 'refresh_token'],
        response_types: ['code'],
        token_endpoint_auth_method: 'none',
      }),
      throw: false,
    });
    if (reg.status !== 201 && reg.status !== 200) {
      throw new Error('client registration failed (HTTP ' + reg.status + ')');
    }
    this.data.clientId = reg.json.client_id;

    const authUrl =
      AUTHORIZE_URL +
      '?client_id=' + encodeURIComponent(this.data.clientId) +
      '&redirect_uri=' + encodeURIComponent(redirectUri) +
      '&response_type=code' +
      '&code_challenge=' + encodeURIComponent(pkce.challenge) +
      '&code_challenge_method=S256' +
      '&scope=' + encodeURIComponent(OAUTH_SCOPE) +
      '&state=' + encodeURIComponent(pkce.state);

    this.lastAuthUrl = authUrl;
    const opened = openInSystemBrowser(authUrl);
    new Notice(
      opened
        ? 'myICOR: finish the login in your browser…'
        : 'myICOR: could not open the browser — use the manual link in the dashboard.',
      8000
    );

    const code = await codePromise;

    const tok = await requestUrl({
      url: TOKEN_URL,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        grant_type: 'authorization_code',
        code: code,
        code_verifier: pkce.verifier,
        redirect_uri: redirectUri,
        client_id: this.data.clientId,
      }),
      throw: false,
    });
    if (tok.status !== 200 || !tok.json.access_token) {
      throw new Error('token exchange failed (HTTP ' + tok.status + ')');
    }
    this.storeTokens(tok.json);
    await this.saveTokens();

    /* Give the Claude sessions in this vault the same context. */
    await this.wireClaude();

    this.refreshExplorerDot();
    new Notice('myICOR: connected.');
  }

  /* In memory only; saveTokens persists. */
  storeTokens(body) {
    this.tokens = {
      access_token: body.access_token,
      refresh_token: body.refresh_token,
      scope: body.scope || OAUTH_SCOPE,
      /* refresh one minute early so a call never rides an expiring token */
      expires_at: Date.now() + Math.max(60, (body.expires_in || 900) - 60) * 1000,
    };
  }

  async ensureToken() {
    if (!this.tokens) throw new Error('not connected');
    if (this.tokens.access_token && Date.now() < this.tokens.expires_at) return this.tokens.access_token;

    const resp = await requestUrl({
      url: TOKEN_URL,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        grant_type: 'refresh_token',
        refresh_token: this.tokens.refresh_token,
      }),
      throw: false,
    });
    if (resp.status !== 200 || !resp.json.access_token) {
      /* Refresh token revoked or expired: drop to disconnected cleanly. */
      this.tokens = null;
      await this.saveTokens();
      this.refreshExplorerDot();
      throw new Error('session expired, please reconnect');
    }
    this.storeTokens(resp.json); /* rotation: the refresh token is replaced */
    await this.saveTokens();
    return this.tokens.access_token;
  }

  async disconnect() {
    this.tokens = null;
    await this.saveTokens();
    this.refreshExplorerDot();
    new Notice('myICOR: disconnected. Your account is untouched; this vault just forgot its keys.');
  }

  /* --------------------------------------------------------- mcp calls --- */

  /* One tool call: the parsed JSON answer. Tools that answer in prose (the Build outline) go through mcpText. */
  async mcpCall(toolName, args) {
    const { text, isError } = await this.mcpRaw(toolName, args);
    const parsed = JSON.parse(text);
    if (isError) throw new Error(parsed.message || parsed.error || 'tool error');
    return parsed;
  }

  /* One tool call whose answer is text, not JSON (get_aynic_course: the ICOR Build outline). */
  async mcpText(toolName, args) {
    const { text, isError } = await this.mcpRaw(toolName, args);
    if (isError) throw new Error(String(text).slice(0, 200) || 'tool error');
    return text;
  }

  async mcpRaw(toolName, args) {
    const token = await this.ensureToken();
    const resp = await requestUrl({
      url: MCP_URL,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json, text/event-stream',
        'Authorization': 'Bearer ' + token,
      },
      body: JSON.stringify({
        jsonrpc: '2.0',
        id: Date.now(),
        method: 'tools/call',
        params: { name: toolName, arguments: args || {} },
      }),
      throw: false,
    });
    if (resp.status === 401) throw new Error('session expired — please reconnect');
    const body = resp.json;
    if (!body || body.error) {
      throw new Error((body && body.error && body.error.message) || 'MCP call failed (HTTP ' + resp.status + ')');
    }
    const content = body.result && body.result.content && body.result.content[0];
    if (!content || content.type !== 'text') throw new Error('unexpected MCP response shape');
    return { text: content.text, isError: !!body.result.isError };
  }

  /* The Home's data in one round of parallel calls. The courses are the page (no courses, no Home: the error says so);
     the journey, the library and the Build outline are each optional, so one tool that fails or is not there for this
     member costs its own piece only. */
  async fetchHomeData() {
    const optional = (p) => p.then((v) => v, () => null);
    const [courses, journey, latest, buildOutline] = await Promise.all([
      this.mcpCall('get_courses'),
      optional(this.mcpCall('get_my_journey')),
      optional(this.mcpCall('get_latest_resources', { limit: 30 })),
      optional(this.mcpText('get_aynic_course')),
    ]);
    return { courses, journey, latest, buildOutline, fetchedAt: new Date() };
  }

  /* ------------------------------------------------- reflection sync ---- */

  /* Escape a string for a double-quoted YAML scalar, flattened to one line. */
  yamlString(v) {
    return '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\s+/g, ' ').trim() + '"';
  }

  reflectionSlug(question) {
    const base = String(question || 'reflection')
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, '')
      .trim()
      .replace(/\s+/g, '-')
      .slice(0, 60)
      .replace(/-+$/, '');
    return base || 'reflection';
  }

  reflectionNote(refl, nowIso) {
    const when = refl.answered_at || refl.completed_at || refl.created_at || nowIso;
    const date = String(when).slice(0, 10);
    const lines = [
      '---',
      'type: icor-reflection',
      'created: ' + nowIso.slice(0, 10),
      'myicor_id: ' + refl.id,
      'category: ' + this.yamlString(refl.question_category || 'Uncategorized'),
      'reflected_at: ' + date,
    ];
    if (typeof refl.quality_score === 'number' && refl.quality_score > 0) {
      lines.push('quality_score: ' + refl.quality_score);
    }
    if (refl.is_pinned === true) lines.push('pinned: true');
    lines.push('synced_at: ' + nowIso, '---', '');

    lines.push('# ' + String(refl.question_text || 'Reflection').replace(/\s+/g, ' ').trim(), '');
    lines.push('> Growth assignment reflection, synced from your myICOR account.', '');
    /* The answer is the user's own text: written VERBATIM, never edited. */
    lines.push('## My answer', '', String(refl.answer).trim(), '');
    if (refl.notes && String(refl.notes).trim()) {
      lines.push('## My notes', '', String(refl.notes).trim(), '');
    }
    const subs = this.renderSubAnswers(refl.question_answers, refl.question_notes);
    if (subs.length) {
      lines.push('## Sub-question answers', '', ...subs, '');
    }
    if (refl.ai_summary && String(refl.ai_summary).trim()) {
      lines.push('## AI summary (from myICOR)', '', String(refl.ai_summary).trim(), '');
    }
    return lines.join('\n');
  }

  /* question_answers is loosely-shaped JSON from the app; render what we can
   * recognize and silently skip the rest rather than dumping raw JSON. */
  renderSubAnswers(answers, notes) {
    const out = [];
    const push = (label, text) => {
      const t = String(text || '').trim();
      if (!t) return;
      if (label) out.push('- **' + String(label).replace(/\s+/g, ' ').trim() + '**', '', '  ' + t, '');
      else out.push('- ' + t, '');
    };
    const walk = (val) => {
      if (Array.isArray(val)) {
        for (const item of val) {
          if (typeof item === 'string') push(null, item);
          else if (item && typeof item === 'object') {
            push(item.question || item.q || item.title || null, item.answer || item.a || item.text || item.value);
          }
        }
      } else if (val && typeof val === 'object') {
        for (const [k, v] of Object.entries(val)) {
          if (typeof v === 'string') push(k, v);
        }
      }
    };
    walk(answers);
    walk(notes);
    return out;
  }

  async syncReflections(progressCb) {
    if (this.syncInFlight) throw new Error('a sync is already running');
    this.syncInFlight = true;
    try {
      const adapter = this.app.vault.adapter;
      const reflectionsDir = this.reflectionsDir();
      if (!(await adapter.exists(reflectionsDir))) await adapter.mkdir(reflectionsDir);

      /* Which reflections already live in the vault? The myicor_id in
       * frontmatter is the sync key; the note content is never compared,
       * because local notes belong to the user once created. */
      const existing = new Set();
      const listing = await adapter.list(reflectionsDir);
      for (const f of listing.files || []) {
        if (!f.endsWith('.md')) continue;
        const head = String(await adapter.read(f)).slice(0, 800);
        const m = head.match(/^myicor_id:\s*([0-9a-f-]{36})\s*$/m);
        if (m) existing.add(m[1]);
      }

      /* Page through every answered reflection remotely. */
      const remote = [];
      let offset = 0;
      for (;;) {
        const page = await this.mcpCall('get_my_notes', { answered_only: true, limit: 100, offset });
        remote.push(...(page.reflections || []));
        if (!page.pagination || !page.pagination.hasMore) break;
        offset += 100;
        if (offset > 5000) break; /* runaway guard */
      }

      /* Reflections with no usable answer are remembered so later syncs do
       * not refetch them forever. */
      const skipped = new Set((this.data.reflectionSync && this.data.reflectionSync.skippedIds) || []);
      const fresh = remote.filter((r) => r.id && !existing.has(r.id) && !skipped.has(r.id));
      const nowIso = new Date().toISOString();
      let created = 0;
      for (const r of fresh) {
        const detail = await this.mcpCall('get_note_details', { note_id: r.id });
        const refl = detail.reflection;
        if (!refl || !refl.answer || !String(refl.answer).trim()) { skipped.add(r.id); continue; }
        const when = refl.answered_at || refl.completed_at || refl.created_at || nowIso;
        let path = reflectionsDir + '/' + String(when).slice(0, 10) + '_' + this.reflectionSlug(refl.question_text) + '.md';
        if (await adapter.exists(path)) {
          path = path.replace(/\.md$/, '-' + String(refl.id).slice(0, 8) + '.md');
        }
        if (await adapter.exists(path)) continue; /* same reflection, same day: already there */
        await adapter.write(path, this.reflectionNote(refl, nowIso));
        created++;
        if (progressCb) progressCb(created, fresh.length);
      }

      this.data.reflectionSync = {
        lastSyncAt: nowIso,
        lastCreated: created,
        totalLocal: existing.size + created,
        totalRemote: remote.length,
        skippedIds: [...skipped].slice(-500),
      };
      await this.saveSettings();
      return this.data.reflectionSync;
    } finally {
      this.syncInFlight = false;
    }
  }

  /* ---------------------------------------------- Claude context wiring -- */

  async wireClaude() {
    const adapter = this.app.vault.adapter;
    let cfg = {};
    if (await adapter.exists('.mcp.json')) {
      try { cfg = JSON.parse(await adapter.read('.mcp.json')); } catch (e) { cfg = {}; }
    }
    if (!cfg.mcpServers || typeof cfg.mcpServers !== 'object') cfg.mcpServers = {};
    /* URL only — Claude Code runs its own OAuth against the same server. */
    cfg.mcpServers.myicor = { type: 'http', url: MCP_URL };
    await adapter.write('.mcp.json', JSON.stringify(cfg, null, 2) + '\n');
  }

  async isClaudeWired() {
    const adapter = this.app.vault.adapter;
    if (!(await adapter.exists('.mcp.json'))) return false;
    try {
      const cfg = JSON.parse(await adapter.read('.mcp.json'));
      return !!(cfg.mcpServers && cfg.mcpServers.myicor);
    } catch (e) {
      return false;
    }
  }

  async ensureGitignore() {
    const adapter = this.app.vault.adapter;
    /* The ignored paths are read from the host at call time, never written
       down: the plugin's folder FOLLOWS the manifest id, the config dir
       itself can be renamed in Obsidian's settings, and the env file is a
       setting. A literal here survives a rename of any of them and then
       guards the wrong path. The env file is covered only while it is the
       backend in use; data.json always, for the builds before 0.15.0 that
       wrote tokens into it. */
    const lines = [this.app.vault.configDir + '/plugins/' + this.manifest.id + '/data.json'];
    if (this.secretsBackend() === 'env-file') {
      lines.push(this.envFilePath());
      /* While the old file (room 06) is the one in use, it is covered too. */
      let at = null;
      try { at = await this.secretsStore().locate(); } catch { at = null; }
      if (at && at.onLegacy && !lines.includes(at.active)) lines.push(at.active);
    }
    let gi = '';
    if (await adapter.exists('.gitignore')) gi = await adapter.read('.gitignore');
    const have = new Set(gi.split('\n').map((l) => l.trim()));
    const missing = lines.filter((l) => !have.has(l));
    if (!missing.length) return;
    const sep = gi === '' || gi.endsWith('\n') ? '' : '\n';
    await adapter.write(
      '.gitignore',
      gi + sep + '\n# ICOR for Life - Connect token store (hard rule 9: secrets never reach git)\n' + missing.join('\n') + '\n'
    );
  }
}

/* ------------------------------------------------------------------------- *
 * Settings tab: where the keys live. Headings are sentence case and carry
 * neither the plugin name nor the word "settings" (directory scanner rules
 * settings-tab/no-manual-html-headings, no-problematic-settings-headings).
 * Inputs are password fields with autocomplete off, cleared after Save. No
 * value reaches a Notice, and the status line reports presence only.
 * ------------------------------------------------------------------------- */

class MyicorConnectSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    this.render(containerEl).catch(() => {
      new Setting(containerEl).setName('Where your keys live').setDesc('The settings could not be read. Close and reopen this tab.');
    });
  }

  async render(el) {
    const plugin = this.plugin;
    const usable = secretStorageUsable(this.app.secretStorage);
    const backend = plugin.secretsBackend();
    const other = backend === 'secret-storage' ? 'env-file' : 'secret-storage';

    new Setting(el).setName('Where your keys live').setHeading();

    new Setting(el)
      .setName('Keys are stored in')
      .setDesc(usable
        ? "Obsidian's keychain (Settings, General, Keychain) keeps the keys on this device, outside the vault, so each device connects on its own. "
          + 'The env file keeps them in a file inside the vault, so one connection follows the vault to every device whose sync carries hidden files (iCloud Drive, git and Dropbox do; Obsidian Sync skips files whose name starts with a dot). '
          + 'Switching moves nothing by itself; use the Move buttons below.'
        : "Obsidian's keychain needs Obsidian 1.11.4 or newer, so on this Obsidian the env file is the only choice.")
      .addDropdown((d) => {
        d.addOption('secret-storage', "Obsidian's keychain")
          .addOption('env-file', 'An env file in the vault')
          .setValue(usable ? plugin.secretsBackendChoice() : 'env-file')
          .setDisabled(!usable)
          .onChange(async (v) => {
            plugin.data.secretsBackend = SECRETS_BACKENDS.includes(v) ? v : defaultSecretsBackend(this.app);
            await plugin.saveSettings();
            await plugin.ensureGitignore();
            await plugin.loadTokens();
            plugin.refreshExplorerDot();
            this.display();
          });
      });

    /* The path is committed on a settled value only (the input's change
       event: blur or Enter), never per keystroke: each keystroke used to
       add a half-typed path to .gitignore and re-read the tokens from a
       file that does not exist. A path that fails the check is refused
       with the reason and the setting keeps its last good value. */
    new Setting(el)
      .setName('Env file')
      .setDesc('Vault-relative path to a file of key=value lines; a line starting with # is a comment. Read only while the env file is the backend in use. '
        + 'Blank means ' + DEFAULT_ENV_FILE_PATH + ', in the vault\'s hidden system folder (Obsidian\'s file list does not show a folder whose name starts with a dot), the same file ICOR for Life - Planner and AI Chat read.')
      .addText((t) => {
        t.setPlaceholder(DEFAULT_ENV_FILE_PATH)
          .setValue(plugin.data.envFilePath === DEFAULT_ENV_FILE_PATH ? '' : (plugin.data.envFilePath || ''));
        t.inputEl.setAttribute('aria-label', 'Env file path');
        t.inputEl.addEventListener('change', async () => {
          const typed = String(t.inputEl.value == null ? '' : t.inputEl.value).trim();
          const next = typed ? normalizeEnvFilePath(typed) : { ok: true, path: DEFAULT_ENV_FILE_PATH, error: '' };
          if (!next.ok) {
            new Notice('myICOR: ' + next.error, 8000);
            t.setValue(plugin.data.envFilePath === DEFAULT_ENV_FILE_PATH ? '' : plugin.data.envFilePath);
            return;
          }
          if (next.path === plugin.data.envFilePath) return;
          plugin.data.envFilePath = next.path;
          await plugin.saveSettings();
          if (backend === 'env-file') {
            await plugin.ensureGitignore();
            await plugin.loadTokens();
            plugin.refreshExplorerDot();
          }
          this.display();
        });
      });

    /* The old keys file (0.17.0): while it is the one in use, a row offers
       the copy to the default place; once the new file is there and the old
       one still is, a row offers to put the old one in the trash. Both act
       only on a click, and both name paths, never a line of the file. */
    if (backend === 'env-file') {
      const store = plugin.secretsBackendFor('env-file');
      let at = null;
      try { at = await store.locate(); } catch { at = null; }
      if (at && at.legacyExists) {
        const row = new Setting(el).setName('Old keys file');
        if (at.onLegacy) {
          row.setDesc('Your keys are still in ' + store.fallback + ', a room this vault no longer needs. Copy the file to ' + store.path + ', the new place ICOR for Life tools read it from. The old file stays until you remove it.')
            .addButton((b) => b.setButtonText('Copy to the new place').setCta().onClick(async () => {
              await plugin.moveEnvFileFromLegacy();
              this.display();
            }));
        } else {
          row.setDesc(store.path + ' is in use. The old copy is still at ' + store.fallback + ', with the keys it held when it was copied. Put it in the trash once no other tool reads it.')
            .addButton((b) => b.setButtonText('Move old file to trash').setWarning().onClick(async () => {
              await plugin.trashLegacyEnvFile();
              this.display();
            }));
        }
      }
    }

    const where = await plugin.secretLocations();
    for (const field of SECRET_FIELD_NAMES) {
      const spec = SECRET_FIELDS[field];
      const row = new Setting(el)
        .setName(spec.label)
        .setDesc(secretStatusText(where[field], backend)
          + ' Env key ' + spec.env + ', keychain id ' + spec.id + '.');
      let pending = '';
      let input = null;
      row.addText((t) => {
        input = t;
        t.inputEl.type = 'password';
        t.inputEl.setAttribute('autocomplete', 'off');
        t.inputEl.setAttribute('aria-label', spec.label);
        t.setPlaceholder('Paste to set by hand').onChange((v) => { pending = v; });
      });
      row.addButton((b) => b.setButtonText('Save').onClick(async () => {
        const v = pending.trim();
        pending = '';
        if (input) input.setValue('');
        if (!v) return;
        try {
          await plugin.setSecretByHand(field, v);
          new Notice('myICOR: ' + spec.label.toLowerCase() + ' saved to ' + BACKEND_LABELS[backend] + '.');
        } catch (e) {
          new Notice('myICOR: could not save the ' + spec.label.toLowerCase() + ' to ' + BACKEND_LABELS[backend] + '. Check the env file path above, or Obsidian\'s keychain.', 12000);
        }
        this.display();
      }));
      if (where[field][other]) {
        row.addButton((b) => b.setButtonText('Move to ' + BACKEND_LABELS[backend]).onClick(async () => {
          try {
            await plugin.moveSecret(field, backend);
            new Notice('myICOR: ' + spec.label.toLowerCase() + ' moved to ' + BACKEND_LABELS[backend] + '.');
          } catch (e) {
            new Notice('myICOR: could not move the ' + spec.label.toLowerCase() + ' to ' + BACKEND_LABELS[backend] + '. Nothing was removed.', 12000);
          }
          this.display();
        }));
      }
    }
  }
}

/* ------------------------------------------------------------------------- *
 * Dashboard view
 * ------------------------------------------------------------------------- */

class DashboardView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.lessonCache = new Map();
  }

  getViewType() { return VIEW_TYPE; }
  getDisplayText() { return 'myICOR'; }
  getIcon() { return 'infinity'; }

  async onOpen() {
    this.root = this.contentEl;
    this.root.addClass('micor-dash');
    /* The INKLINE theme's control skins stand down inside: every control here has exactly one edge, its own. */
    this.root.setAttribute('data-ink-plugin', '');
    await this.render();
  }

  openLink(url) {
    if (url) window.open(url);
  }

  setPage(page) {
    if (!PAGES.some((p) => p.key === (PAGE_ALIASES[page] || page))) return;
    this.page = PAGE_ALIASES[page] || page;
    this.render();
  }

  async render() {
    this.root.empty();
    if (!this.plugin.isConnected()) {
      this.renderConnectHero();
      return;
    }
    this.renderShell();
  }

  /* ------------------------------------------------------------- shell -- */

  /* One bar: the mark and myICOR, the pages, and three quiet icon buttons. No masthead and no drawn stroke: the page
     head says where you are, and the marker is kept for an action. */
  renderShell() {
    const current = pageFor(this.page || 'home');

    const top = this.root.createDiv({ cls: 'micor-top' });
    const brand = top.createDiv({ cls: 'micor-top-brand' });
    const m = brand.createDiv({ cls: 'micor-top-mark' });
    m.innerHTML = MARK_SVG;
    brand.createSpan({ cls: 'micor-top-name', text: 'myICOR' });

    const nav = top.createEl('nav', { cls: 'micor-pages', attr: { 'aria-label': 'Pages' } });
    for (const page of PAGES) {
      const item = nav.createEl('button', { cls: 'micor-pages-item' + (page.key === current.key ? ' is-active' : '') });
      if (page.key === current.key) item.setAttribute('aria-current', 'page');
      setIcon(item.createSpan({ cls: 'micor-pages-icon' }), page.icon);
      item.createSpan({ cls: 'micor-pages-label', text: page.label });
      item.addEventListener('click', () => this.setPage(page.key));
    }

    const actions = top.createDiv({ cls: 'micor-top-actions' });
    const iconBtn = (icon, label, fn) => {
      const b = actions.createEl('button', { cls: 'micor-iconbtn', attr: { 'aria-label': label } });
      setIcon(b, icon);
      b.addEventListener('click', fn);
      return b;
    };
    iconBtn('external-link', 'Open app.myicor.com', () => this.openLink(BASE_URL));
    iconBtn('refresh-cw', 'Refresh this page', () => {
      this.plugin.lastHome = null;
      if (this.pageCache) this.pageCache.clear();
      this.render();
    });
    iconBtn('log-out', 'Disconnect this vault', async () => {
      await this.plugin.disconnect();
      this.plugin.lastHome = null;
      this.render();
    });

    const page = this.root.createDiv({ cls: 'micor-page micor-page--' + current.key });
    if (current.key === 'home') { this.renderHome(page); return; }
    this.pageHead(page, current.eyebrow, current.title);
    this.renderPage(page.createDiv({ cls: 'micor-page-body' }), current.key);
  }

  async renderPage(body, page) {
    if (page === 'search') { this.renderSearch(body, true); return; }
    if (page === 'trends') { await this.renderTrendsPage(body); return; }
    if (page === 'latest') { await this.renderLatestPage(body); return; }
    if (page === 'announcements') { await this.renderBoardPage(body); return; }
  }

  /* A page head (INKLINE .ik-pagehead): the eyebrow, the title; returns the head so a page can add its actions. */
  pageHead(parent, eyebrow, title) {
    const head = parent.createDiv({ cls: 'micor-pagehead' });
    const words = head.createDiv({ cls: 'micor-pagehead-words' });
    if (eyebrow) words.createDiv({ cls: 'micor-eyebrow', text: eyebrow });
    words.createEl('h1', { cls: 'micor-pagehead-title', text: title });
    return head;
  }

  /* A section head (INKLINE .ik-section-head): the title, and a link or a quiet line at the end. */
  sectionHead(parent, title, end) {
    const head = parent.createDiv({ cls: 'micor-section-head' });
    head.createEl('h2', { text: title });
    if (end && end.url) {
      const a = head.createEl('button', { cls: 'micor-link', text: end.label });
      a.addEventListener('click', () => this.openLink(end.url));
    } else if (end && end.label) {
      head.createSpan({ cls: 'micor-small', text: end.label });
    }
    return head;
  }

  /* ------------------------------------------------- shared page bits --- */

  skeletonRows(parent, n) {
    const box = parent.createDiv({ cls: 'micor-skeleton', attr: { role: 'status', 'aria-live': 'polite', 'aria-label': 'Loading' } });
    for (let i = 0; i < n; i++) {
      const row = box.createDiv({ cls: 'micor-skeleton-row' });
      row.createDiv({ cls: 'micor-track micor-track-kicker' });
      row.createDiv({ cls: 'micor-track micor-track-title' });
    }
    return box;
  }

  emptyState(parent, icon, text, hand) {
    const box = parent.createDiv({ cls: 'micor-blank' });
    setIcon(box.createDiv({ cls: 'micor-blank-icon' }), icon);
    box.createDiv({ cls: 'micor-blank-text', text });
    if (hand) box.createDiv({ cls: 'micor-hand-note', text: hand });
    return box;
  }

  renderPageError(body, err) {
    const box = body.createDiv({ cls: 'micor-blank' });
    setIcon(box.createDiv({ cls: 'micor-blank-icon' }), 'unplug');
    box.createDiv({ cls: 'micor-blank-text', text: 'Could not load this page.' });
    box.createDiv({ cls: 'micor-error-note', text: String(err.message || err) });
    const retry = box.createEl('button', { cls: 'micor-connect-btn', text: 'Try again' });
    retry.addEventListener('click', () => this.render());
  }

  /* Fetch a page tool with cache; 'pending' when the server has not
   * shipped the tool yet. */
  async fetchTool(toolName, args) {
    if (!this.pageCache) this.pageCache = new Map();
    if (this.pageCache.has(toolName)) return this.pageCache.get(toolName);
    try {
      const payload = await this.plugin.mcpCall(toolName, args || {});
      this.pageCache.set(toolName, payload);
      return payload;
    } catch (e) {
      if (/unknown tool|not found|unrecognized|-32601/i.test(String(e.message))) return { pending: true };
      throw e;
    }
  }

  /* -------------------------------------------------------------- home -- */

  /* The Home. Stale but drawn beats a blank: the last data renders at once and the fresh data replaces it in place. */
  async renderHome(page) {
    const head = this.pageHead(page, DAYS[new Date().getDay()], 'Find your way back to clear');
    const upSlot = head.createDiv({ cls: 'micor-pagehead-actions' });
    const body = page.createDiv({ cls: 'micor-home' });
    const draw = (data) => { body.empty(); upSlot.empty(); this.renderHomeBody(body, upSlot, data); };
    if (this.plugin.lastHome) {
      draw(this.plugin.lastHome);
      this.plugin.fetchHomeData().then((data) => {
        this.plugin.lastHome = data;
        if (body.isConnected && (this.page || 'home') === 'home') draw(data);
      }).catch(() => { /* the drawn page stays; the next open tries again */ });
      return;
    }
    this.homeSkeleton(body);
    try {
      const data = await this.plugin.fetchHomeData();
      this.plugin.lastHome = data;
      draw(data);
    } catch (e) {
      body.empty();
      this.renderPageError(body, e);
    }
  }

  /* The shape of the Home while it loads: three library cards and six place cards, still. */
  homeSkeleton(body) {
    const box = body.createDiv({ cls: 'micor-home-skeleton', attr: { role: 'status', 'aria-live': 'polite', 'aria-label': 'Loading' } });
    const lib = box.createDiv({ cls: 'micor-grid micor-grid--three' });
    for (let i = 0; i < 3; i++) lib.createDiv({ cls: 'micor-libcard is-skeleton' }).createDiv({ cls: 'micor-libcard-media' });
    const cards = box.createDiv({ cls: 'micor-grid micor-grid--places' });
    for (let i = 0; i < 6; i++) cards.createDiv({ cls: 'micor-placecard is-skeleton' });
  }

  renderHomeBody(body, upSlot, data) {
    const model = homeModel(data);
    this.renderUpNext(upSlot, model.next);

    if (model.newest.length) {
      const sec = body.createEl('section', { cls: 'micor-home-sect' });
      this.sectionHead(sec, 'New from Tom and Paco', { label: 'The library', url: BASE_URL + '/library' });
      const grid = sec.createDiv({ cls: 'micor-grid micor-grid--three' });
      for (const item of model.newest) this.libraryCard(grid, item);
    }

    const road = body.createEl('section', { cls: 'micor-home-sect' });
    this.sectionHead(road, 'Your progress', { label: 'The roadmap and your system' });
    const cards = road.createDiv({ cls: 'micor-grid micor-grid--places' });
    for (const c of model.cards) this.placeCard(cards, c);

    const pair = body.createDiv({ cls: 'micor-grid micor-grid--two' });
    const away = pair.createEl('section', { cls: 'micor-home-sect' });
    this.sectionHead(away, 'On app.myicor.com', { label: 'Open', url: BASE_URL });
    const awayList = away.createDiv({ cls: 'micor-list' });
    for (const e of model.elsewhere) this.row(awayList, { icon: e.icon, title: e.title, sub: e.sub, onClick: () => this.openLink(e.url) });

    const here = pair.createEl('section', { cls: 'micor-home-sect' });
    this.sectionHead(here, 'In this vault');
    this.renderVaultRows(here.createDiv({ cls: 'micor-list' }));

    const foot = body.createDiv({ cls: 'micor-home-foot' });
    foot.setText('Live from app.myicor.com through the myICOR MCP · refreshed ' + data.fetchedAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
  }

  /* Where you left off, as one line (INKLINE .ik-upnext): the course first, its next lesson once get_lessons answers. */
  renderUpNext(slot, course) {
    if (!course) return;
    const line = slot.createEl('button', { cls: 'micor-upnext' });
    line.createSpan({ cls: 'micor-upnext-tag', text: 'Up next' });
    const title = line.createSpan({ cls: 'micor-upnext-title', text: course.name || 'Your next lesson' });
    const sub = line.createSpan({ cls: 'micor-upnext-sub' });
    setIcon(line.createSpan({ cls: 'micor-upnext-icon' }), 'arrow-right');
    let url = course.url;
    line.addEventListener('click', () => this.openLink(url));
    (async () => {
      let payload = this.lessonCache.get(course.id);
      if (!payload) {
        payload = await this.plugin.mcpCall('get_lessons', { course_id: course.id });
        this.lessonCache.set(course.id, payload);
      }
      const next = (payload.lessons || []).find((l) => !l.completed);
      if (!next) return;
      title.setText(next.title || course.name);
      sub.setText(course.name || '');
      url = next.url || course.url;
    })().catch(() => { /* the course stays as the line */ });
  }

  /* A library card (INKLINE .ik-mcard as the app's LibraryCard): the picture, the type, the title, who and when. */
  libraryCard(grid, item) {
    const card = grid.createEl('button', { cls: 'micor-libcard' });
    const media = card.createDiv({ cls: 'micor-libcard-media' });
    if (item.image_url) media.createEl('img', { attr: { src: item.image_url, loading: 'lazy', decoding: 'async', alt: '' } });
    const words = card.createDiv({ cls: 'micor-libcard-words' });
    const kind = [String(item.type || 'Resource')];
    if (item.duration_minutes) kind.push(item.duration_minutes + ' min');
    words.createDiv({ cls: 'micor-label', text: kind.join(' · ') });
    words.createDiv({ cls: 'micor-libcard-title', text: item.title || 'Untitled' });
    const meta = [item.author, shortDate(item.published_date)].filter(Boolean).join(' · ');
    if (meta) words.createDiv({ cls: 'micor-libcard-sub', text: meta });
    if (item.url) card.addEventListener('click', () => this.openLink(item.url));
  }

  /* A place card (INKLINE .ik-placecard): a lit cover in the place's light, its mark, one line, the progress, Open. */
  placeCard(grid, c) {
    const card = grid.createEl('button', { cls: 'micor-placecard', attr: { 'data-place': c.place, 'aria-label': c.label + ': ' + c.line } });
    const mark = card.createSpan({ cls: 'micor-placemark' });
    if (c.text || !PLACE_MARK_SVG[c.place]) {
      mark.setText('ICOR ' + (c.text || c.label.replace(/^ICOR /, '')));
    } else {
      mark.setText('ICOR');
      mark.createEl('img', { attr: { src: 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(PLACE_MARK_SVG[c.place]), alt: '' } });
    }
    card.createEl('p', { cls: 'micor-placecard-line', text: c.line });
    const meter = card.createSpan({ cls: 'micor-placecard-meter' });
    if (c.frac != null) {
      const bar = meter.createSpan({ cls: 'micor-meter' });
      bar.createSpan({ cls: 'micor-meter-fill' }).style.setProperty('--micor-p', String(Math.max(0, Math.min(1, c.frac))));
      meter.createEl('small', { text: c.count });
    } else {
      meter.createEl('small', { text: c.note });
    }
    const foot = card.createSpan({ cls: 'micor-placecard-foot' });
    const open = foot.createSpan({ cls: 'micor-placecard-open', text: 'Open' });
    setIcon(open.createSpan({ cls: 'micor-placecard-arrow' }), 'arrow-right');
    if (c.tag) foot.createSpan({ cls: 'micor-chip micor-chip--place', text: c.tag });
    card.addEventListener('click', () => this.openLink(c.url));
  }

  /* A list row (INKLINE .ik-row): an icon, a title and a line, and at the end a chevron or the row's own button. */
  row(list, o) {
    const r = list.createDiv({ cls: 'micor-row' + (o.onClick ? ' is-clickable' : '') });
    if (o.onClick) {
      r.setAttribute('role', 'button');
      r.setAttribute('tabindex', '0');
      r.addEventListener('click', o.onClick);
      r.addEventListener('keydown', (ev) => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); o.onClick(); } });
    }
    setIcon(r.createSpan({ cls: 'micor-row-lead' + (o.ok ? ' is-ok' : '') }), o.icon);
    const main = r.createSpan({ cls: 'micor-row-main' });
    main.createSpan({ cls: 'micor-row-title', text: o.title });
    const sub = main.createSpan({ cls: 'micor-row-sub', text: o.sub || '' });
    const end = r.createSpan({ cls: 'micor-row-end' });
    if (o.button) {
      const b = end.createEl('button', { cls: 'micor-btn micor-btn-quiet', text: o.button.label });
      b.addEventListener('click', (ev) => { ev.stopPropagation(); o.button.onClick(b, sub); });
    } else if (o.onClick) {
      setIcon(end.createSpan({ cls: 'micor-row-chevron' }), 'chevron-right');
    }
    return r;
  }

  /* What Connect does in this vault: the reflections sync, Claude's connection, and the knowledge search. */
  async renderVaultRows(list) {
    const st = this.plugin.data.reflectionSync;
    let where = REFLECTIONS_ROOM + ' Inner World/' + REFLECTIONS_SUBDIR;
    try { where = this.plugin.reflectionsDir(); } catch { /* no room 04: the default name stands */ }
    const syncSub = (s) => (s ? s.totalLocal + ' in ' + where + ' · last sync ' + new Date(s.lastSyncAt).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : 'Your Growth Assignment reflections, as notes you own');
    this.row(list, {
      icon: 'notebook-pen', ok: !!st, title: 'Reflections', sub: syncSub(st),
      button: {
        label: st ? 'Sync again' : 'Sync',
        onClick: async (b, sub) => {
          b.setAttr('disabled', 'true');
          b.setText('Syncing…');
          try {
            const r = await this.plugin.syncReflections((done, total) => b.setText(done + ' of ' + total));
            b.removeAttribute('disabled');
            b.setText('Sync again');
            sub.setText(syncSub(this.plugin.data.reflectionSync));
            new Notice('myICOR: ' + r.lastCreated + ' new reflection' + (r.lastCreated === 1 ? '' : 's') + ' synced.');
          } catch (e) {
            b.removeAttribute('disabled');
            b.setText('Sync');
            new Notice('myICOR: sync failed: ' + e.message);
          }
        },
      },
    });
    this.row(list, { icon: 'search', title: 'Search myICOR', sub: 'Lessons, resources and answers, from here', onClick: () => this.setPage('search') });
    const wired = await this.plugin.isClaudeWired();
    this.row(list, {
      icon: 'bot', ok: wired, title: 'Claude in this vault',
      sub: wired ? 'Can search myICOR lessons, resources and recordings' : 'Not connected yet',
      button: wired ? null : { label: 'Connect', onClick: async () => { await this.plugin.wireClaude(); this.render(); } },
    });
  }

  /* ------------------------------------------------------------- search -- */

  renderSearch(parent, focus) {
    const wrap = parent.createDiv({ cls: 'micor-search' });
    const line = wrap.createDiv({ cls: 'micor-search-line' });
    setIcon(line.createDiv({ cls: 'micor-search-icon' }), 'search');
    const input = line.createEl('input', {
      cls: 'micor-search-input',
      attr: { type: 'text', placeholder: 'Search myICOR: lessons, resources, founder answers…', spellcheck: 'false' },
    });
    const clear = line.createEl('button', { cls: 'micor-search-clear', attr: { 'aria-label': 'Clear search' } });
    setIcon(clear, 'x');
    const results = wrap.createDiv({ cls: 'micor-search-results' });
    clear.addEventListener('click', () => { input.value = ''; results.empty(); line.removeClass('has-value'); input.focus(); });

    const run = async () => {
      const query = input.value.trim();
      if (!query) { results.empty(); return; }
      results.empty();
      this.skeletonRows(results, 2);
      try {
        const payload = await this.plugin.mcpCall('search_myicor', { query, k: 10 });
        const hits = payload.results || [];
        results.empty();
        if (!hits.length) {
          this.emptyState(results, 'search', 'Nothing found.', 'try fewer, bigger words');
          return;
        }
        for (const hit of hits) {
          const row = results.createDiv({ cls: 'micor-hit' + (hit.deep_link ? ' is-clickable' : '') });
          const kicker = row.createDiv({ cls: 'micor-hit-kicker' });
          kicker.createSpan({ text: String(hit.source_type || 'result').toUpperCase() });
          if (hit.founder_authority) kicker.createSpan({ text: ' · FOUNDER' });
          if (hit.date) kicker.createSpan({ text: ' · ' + kickerDate(hit.date) });
          row.createDiv({ cls: 'micor-hit-title', text: hit.title || 'Untitled' });
          if (hit.snippet && hit.snippet !== hit.title) row.createDiv({ cls: 'micor-hit-snippet', text: hit.snippet });
          if (hit.deep_link) row.addEventListener('click', () => this.openLink(hit.deep_link));
        }
      } catch (e) {
        results.empty();
        results.createDiv({ cls: 'micor-error-note', text: 'Search failed: ' + e.message });
      }
    };

    input.addEventListener('input', () => line.toggleClass('has-value', input.value.length > 0));
    input.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') run(); });
    if (focus) window.setTimeout(() => input.focus(), 30);
  }

  /* ------------------------------------------------------------- trends -- */

  async renderTrendsPage(body) {
    this.skeletonRows(body, 3);
    let payload;
    try {
      payload = await this.fetchTool('get_trend_reports', { limit: 10 });
    } catch (e) {
      body.empty();
      this.renderPageError(body, e);
      return;
    }
    body.empty();
    const reports = payload.reports || [];
    if (!reports.length) {
      this.emptyState(body, 'trending-up', 'No published trend reports yet.', 'the radar sweeps weekly');
      return;
    }
    const list = body.createDiv({ cls: 'micor-report-list' });
    for (const r of reports) {
      const row = list.createDiv({ cls: 'micor-report is-clickable' });
      const kick = [];
      kick.push('TREND REPORT');
      if (r.report_date) kick.push(kickerDate(r.report_date));
      if (r.like_count) kick.push('♥ ' + r.like_count);
      if (r.comment_count) kick.push(r.comment_count + ' COMMENTS');
      row.createDiv({ cls: 'micor-report-kicker', text: kick.join(' · ') });
      row.createDiv({ cls: 'micor-report-title', text: r.title || 'Trend report' });
      if (r.subtitle) row.createDiv({ cls: 'micor-report-subtitle', text: r.subtitle });
      const heads = Array.isArray(r.headlines) ? r.headlines : [];
      if (heads.length) {
        const hl = row.createDiv({ cls: 'micor-report-headlines' });
        for (const h of heads.slice(0, 3)) {
          const line = hl.createDiv({ cls: 'micor-report-headline' });
          line.createDiv({ cls: 'micor-dashline' });
          line.createSpan({ text: typeof h === 'string' ? h : (h && (h.title || h.headline)) || '' });
        }
      }
      row.addEventListener('click', () => this.openLink(BASE_URL + '/trend-reports/' + r.id));
    }
  }

  /* ------------------------------------------------------------- latest -- */

  async renderLatestPage(body) {
    const sk = body.createDiv({ cls: 'micor-grid micor-grid--three micor-grid--shelf', attr: { role: 'status', 'aria-live': 'polite', 'aria-label': 'Loading' } });
    for (let i = 0; i < 6; i++) sk.createDiv({ cls: 'micor-libcard is-skeleton' }).createDiv({ cls: 'micor-libcard-media' });
    let payload;
    try {
      payload = await this.fetchTool('get_latest_resources', { limit: 18 });
    } catch (e) {
      body.empty();
      this.renderPageError(body, e);
      return;
    }
    body.empty();
    if (payload.pending) { this.renderPendingTool(body, 'get_latest_resources', 'newspaper', '/resources/all'); return; }
    const items = payload.resources || [];
    if (!items.length) {
      this.emptyState(body, 'newspaper', 'Nothing here yet.', 'fresh ink lands weekly');
      return;
    }
    /* the same library card as the Home's, three across */
    const grid = body.createDiv({ cls: 'micor-grid micor-grid--three micor-grid--shelf' });
    for (const item of items) this.libraryCard(grid, item);
  }

  /* ------------------------------------------------------ announcements -- */

  async renderBoardPage(body) {
    this.skeletonRows(body, 5);
    let payload;
    try {
      payload = await this.fetchTool('get_announcements', { limit: 12 });
    } catch (e) {
      body.empty();
      this.renderPageError(body, e);
      return;
    }
    body.empty();
    if (payload.pending) { this.renderPendingTool(body, 'get_announcements', 'megaphone', '/announcements'); return; }
    const items = payload.announcements || [];
    if (!items.length) {
      this.emptyState(body, 'megaphone', 'Nothing on the board yet.', 'announcements land here first');
      return;
    }

    /* billboard hero: first featured, else newest. Its button is the page's one marker; nothing else wears it. */
    const heroItem = items.find((a) => a.is_featured) || items[0];
    const rest = items.filter((a) => a !== heroItem);

    const hero = body.createDiv({ cls: 'micor-billboard' });
    const content = hero.createDiv({ cls: 'micor-billboard-content' });
    const kicker = content.createDiv({ cls: 'micor-billboard-kicker' });
    kicker.createSpan({ text: heroItem.is_featured ? 'FEATURED' : 'LATEST' });
    if (heroItem.published_at) kicker.createSpan({ text: ' · ' + kickerDate(heroItem.published_at) });
    content.createEl('h2', { cls: 'micor-billboard-title', text: heroItem.title || 'Announcement' });
    if (heroItem.excerpt) content.createDiv({ cls: 'micor-billboard-excerpt', text: heroItem.excerpt });
    const actions = content.createDiv({ cls: 'micor-billboard-actions' });
    const cta = actions.createEl('button', { cls: 'micor-billboard-cta', text: heroItem.cta_label || 'Read more' });
    cta.addEventListener('click', () => this.openLink(heroItem.cta_url || heroItem.url));
    const hm = [];
    if (heroItem.like_count) hm.push('♥ ' + heroItem.like_count);
    if (heroItem.reply_count) hm.push(heroItem.reply_count + ' COMMENTS');
    if (hm.length) actions.createDiv({ cls: 'micor-billboard-meta', text: hm.join(' · ') });
    const cover = hero.createDiv({ cls: 'micor-billboard-cover' });
    if (heroItem.image_url) cover.createEl('img', { attr: { src: heroItem.image_url, loading: 'lazy', alt: heroItem.title || '' } });
    else cover.createDiv({ cls: 'micor-tile-fallback', text: 'ANNOUNCEMENT' });

    /* the rows below */
    const list = body.createDiv({ cls: 'micor-ann-list' });
    for (const a of rest) {
      const row = list.createDiv({ cls: 'micor-ann-row is-clickable' });
      const rb = row.createDiv({ cls: 'micor-ann-body' });
      const k = rb.createDiv({ cls: 'micor-hit-kicker' });
      if (a.is_featured) k.createSpan({ text: 'FEATURED · ' });
      k.createSpan({ text: 'ANNOUNCEMENT' + (a.published_at ? ' · ' + kickerDate(a.published_at) : '') });
      rb.createDiv({ cls: 'micor-hit-title', text: a.title || 'Untitled' });
      const meta = rb.createDiv({ cls: 'micor-ann-meta' });
      const parts = [];
      if (a.like_count) parts.push('♥ ' + a.like_count);
      if (a.reply_count) parts.push(a.reply_count + ' COMMENTS');
      meta.createSpan({ text: parts.join(' · ') });
      if (a.cta_label && a.cta_url) {
        const cl = meta.createEl('a', { cls: 'micor-ann-cta', text: (parts.length ? ' · ' : '') + String(a.cta_label).toUpperCase() + ' ↗', href: a.cta_url });
        cl.addEventListener('click', (ev) => { ev.preventDefault(); ev.stopPropagation(); this.openLink(a.cta_url); });
      }
      if (a.image_url) {
        const th = row.createDiv({ cls: 'micor-ann-thumb' });
        th.createEl('img', { attr: { src: a.image_url, loading: 'lazy', alt: '' } });
      }
      if (a.url) row.addEventListener('click', () => this.openLink(a.url));
    }
  }

  renderPendingTool(body, toolName, icon, appPath) {
    const box = this.emptyState(body, icon, 'This page is wired and waiting for the ' + toolName + ' tool in the next myICOR MCP release.', 'it lights up on its own');
    const open = box.createEl('button', { cls: 'micor-quiet-btn', text: 'OPEN IN MYICOR FOR NOW' });
    open.addEventListener('click', () => this.openLink(BASE_URL + appPath));
  }

  /* ------------------------------------------------------ connect hero --- */

  renderConnectHero() {
    const hero = this.root.createDiv({ cls: 'micor-hero' });
    const mark = hero.createDiv({ cls: 'micor-hero-mark' });
    mark.innerHTML = MARK_SVG;
    hero.createEl('h1', { text: 'myICOR', cls: 'micor-hero-title' });
    hero.createDiv({ cls: 'micor-hero-sub', text: 'Connect this vault to your app.myicor.com account.' });

    const points = hero.createDiv({ cls: 'micor-hero-points' });
    for (const [icon, text] of [
      ['gauge', 'Your ICOR Journey, courses, and Growth Assignment progress, live in the vault'],
      ['search', 'Search lessons, resources, and founder answers without leaving Obsidian'],
      ['bot', 'Claude sessions in this scaffold gain myICOR context through the same connection'],
      ['lock', 'OAuth in your browser. Keys stay on this machine and never reach git'],
    ]) {
      const row = points.createDiv({ cls: 'micor-hero-point' });
      setIcon(row.createDiv({ cls: 'micor-hero-point-icon' }), icon);
      row.createSpan({ text });
    }

    const btn = hero.createEl('button', { cls: 'micor-connect-btn', text: 'Connect to myICOR' });
    const note = hero.createDiv({ cls: 'micor-hero-note', text: 'Your browser will open for login and consent.' });
    const fallback = hero.createDiv({ cls: 'micor-auth-fallback' });
    btn.addEventListener('click', async () => {
      btn.setAttr('disabled', 'true');
      btn.setText('Waiting for your browser…');
      note.setText('Finish the login in the browser tab that just opened.');
      window.setTimeout(() => {
        if (!this.plugin.lastAuthUrl || fallback.hasChildNodes()) return;
        fallback.createSpan({ text: 'Browser did not open? ' });
        const link = fallback.createEl('a', { text: 'Open the login page', href: this.plugin.lastAuthUrl });
        link.addEventListener('click', (ev) => {
          ev.preventDefault();
          if (this.plugin.lastAuthUrl) openInSystemBrowser(this.plugin.lastAuthUrl);
        });
        fallback.createSpan({ text: ' or ' });
        const copy = fallback.createEl('a', { text: 'copy the link', href: '#' });
        copy.addEventListener('click', async (ev) => {
          ev.preventDefault();
          if (this.plugin.lastAuthUrl) {
            await navigator.clipboard.writeText(this.plugin.lastAuthUrl);
            new Notice('myICOR: login link copied — paste it into any browser.');
          }
        });
      }, 2500);
      try {
        await this.plugin.connect();
        await this.render();
      } catch (e) {
        btn.removeAttribute('disabled');
        btn.setText('Connect to myICOR');
        fallback.empty();
        note.setText('Connection failed: ' + e.message);
        note.addClass('is-error');
      }
    });
  }
}

/* ------------------------------------------------------------------------- *
 * Room dashboards — six vault-local dashboards, one per room. All metrics
 * are computed from the vault itself (files, frontmatter, mtimes): code
 * does the counting. No myICOR connection required.
 * ------------------------------------------------------------------------- */

class RoomDashboardView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.room = ROOMS[0].path;
  }

  getViewType() { return ROOM_VIEW_TYPE; }
  getDisplayText() {
    const room = roomFor(this.room);
    return room ? room.path.replace(/^\d+ /, '') : 'Room';
  }
  getIcon() { return 'gauge'; }

  getState() { return { room: this.room }; }
  async setState(state, result) {
    /* Workspace state stores a PATH, and a room can be renamed between two
     * launches. Matching on the number too means a rename reopens the room the
     * user left open instead of silently dropping them back to room 00. */
    const room = state && state.room ? roomFor(state.room) : null;
    if (room) this.room = room.path;
    await super.setState(state, result);
    this.renderRoom();
  }

  async onOpen() {
    this.root = this.contentEl;
    this.root.addClass('micor-dash');
    this.renderRoom();
  }

  /* ------------------------------------------------------- vault access -- */

  files(sub) {
    const prefix = this.room + (sub ? '/' + sub : '') + '/';
    return this.plugin.app.vault.getFiles().filter((f) => f.path.startsWith(prefix));
  }

  notes(sub) {
    return this.files(sub).filter((f) => f.extension === 'md' && f.name !== 'README.md' && f.name !== '_template.md');
  }

  fm(file) {
    const c = this.plugin.app.metadataCache.getFileCache(file);
    return (c && c.frontmatter) || {};
  }

  daysAgo(ms) {
    return Math.floor((Date.now() - ms) / 86400000);
  }

  ageText(ms) {
    const d = this.daysAgo(ms);
    if (d <= 0) return 'TODAY';
    if (d === 1) return 'YESTERDAY';
    return d + ' DAYS AGO';
  }

  openFile(file) {
    this.plugin.app.workspace.getLeaf(false).openFile(file);
  }

  /* ---------------------------------------------------------- rendering -- */

  renderRoom() {
    if (!this.root) return;
    this.root.empty();
    const room = roomFor(this.room) || ROOMS[0];

    const mast = this.root.createDiv({ cls: 'micor-masthead' });
    mast.createDiv({ cls: 'micor-masthead-kicker', text: room.kicker });
    const h1 = mast.createEl('h1', { cls: 'micor-masthead-title', text: room.title });
    const hand = h1.createSpan({ cls: 'micor-masthead-hand', text: room.hand });
    hand.setAttribute('aria-hidden', 'true');
    strokeEl(mast, 'micor-masthead-stroke');

    const body = this.root.createDiv({ cls: 'micor-page' });
    const fn = {
      scratchpad: () => this.renderScratchpad(body),
      inbox: () => this.renderInbox(body),
      inner: () => this.renderInner(body),
      assets: () => this.renderAssets(body),
      outer: () => this.renderOuter(body),
    }[room.key];
    fn && fn();

    const footer = this.root.createDiv({ cls: 'micor-footer' });
    footer.createSpan({ text: 'COMPUTED LIVE FROM THE VAULT · ' + new Date().toLocaleTimeString() });
  }

  sect(body, kicker, bodyText) {
    const sec = body.createDiv({ cls: 'micor-sect in' });
    sec.createSpan({ cls: 'micor-sect-kicker', text: kicker });
    if (bodyText) sec.createDiv({ cls: 'micor-sect-body', text: bodyText });
    return sec;
  }

  slabBand(body) {
    return body.createDiv({ cls: 'micor-slabs micor-room-slabs' });
  }

  slab(band, value, small, label, marker) {
    const el = band.createDiv({ cls: 'micor-slab' + (marker ? ' is-marker' : '') });
    const b = el.createEl('b', { text: String(value) });
    if (small) b.createEl('small', { text: ' ' + small });
    el.createEl('span', { text: label });
  }

  fileRows(sec, files, opts) {
    const o = opts || {};
    if (!files.length) {
      sec.createDiv({ cls: 'micor-hand-note', text: o.empty || 'nothing here yet' });
      return;
    }
    const list = sec.createDiv({ cls: 'micor-gap-list' });
    for (const f of files) {
      const row = list.createDiv({ cls: 'micor-hit is-clickable micor-room-row' });
      const kicker = row.createDiv({ cls: 'micor-hit-kicker' });
      const rel = f.path.slice(this.room.length + 1);
      const folder = rel.includes('/') ? rel.slice(0, rel.lastIndexOf('/')).toUpperCase() : null;
      const parts = [];
      if (o.kicker) parts.push(o.kicker(f));
      else {
        if (folder) parts.push(folder);
        parts.push(this.ageText(f.stat.mtime));
      }
      kicker.setText(parts.join(' · '));
      row.createDiv({ cls: 'micor-hit-title', text: o.title ? o.title(f) : f.basename });
      row.addEventListener('click', () => this.openFile(f));
    }
  }

  recent(files, n) {
    return [...files].sort((a, b) => b.stat.mtime - a.stat.mtime).slice(0, n || 6);
  }

  /* ------------------------------------------------------ 00 scratchpad -- */

  renderScratchpad(body) {
    const notes = this.notes();
    const daily = notes.filter((f) => /^\d{4}-\d{2}-\d{2}$/.test(f.basename));
    /* A quick capture is named by the moment it was made, in one of the three
       shapes the scaffold's validator accepts: YYYY-MM-DD-HHmmss (the Unique
       note creator the new-note button runs, -N on a same-second collision),
       the older YYYYMMDDHHmm (Obsidian's " 2" on a collision, " - title" when
       the member names it after the fact), and YYYYMMDDHHmmss with -N. */
    const captures = notes.filter((f) => /^(\d{4}-\d{2}-\d{2}-\d{6}(-\d+)?|\d{12}( \d+)?( - .+)?|\d{14}(-\d+)?)$/.test(f.basename));
    const processed = notes.filter((f) => this.fm(f).processed === true);
    const unprocessed = notes.filter((f) => this.fm(f).processed !== true);

    const band = this.slabBand(body);
    this.slab(band, unprocessed.length, null, 'waiting for processing', unprocessed.length > 0);
    this.slab(band, processed.length, null, 'processed and stamped');
    this.slab(band, daily.length, null, 'daily notes');
    this.slab(band, captures.length, null, 'quick captures');

    const todo = this.sect(body, 'NEEDS PROCESSING', unprocessed.length
      ? 'Unprocessed thought is invisible thought. Ask Larry to process the scratchpad.'
      : null);
    this.fileRows(todo, this.recent(unprocessed, 6), { empty: 'everything is stamped — clean desk' });

    const latest = this.sect(body, 'LATEST INK');
    this.fileRows(latest, this.recent(notes, 6), { empty: 'no notes yet — hit new note and write' });
  }

  /* ----------------------------------------------------------- 01 inbox -- */

  renderInbox(body) {
    const active = this.notes().filter((f) => !f.path.includes('/archive/'));
    const archived = this.notes().filter((f) => f.path.includes('/archive/'));
    const scanner = this.files('Scanner Inbox');
    const oldest = active.length ? Math.max(...active.map((f) => this.daysAgo(f.stat.ctime))) : 0;

    const band = this.slabBand(body);
    this.slab(band, active.length, null, 'waiting in the inbox', active.length > 0);
    this.slab(band, archived.length, null, 'processed and archived');
    this.slab(band, scanner.length, null, 'in the scanner inbox');
    this.slab(band, active.length ? oldest : '—', active.length ? (oldest === 1 ? 'day' : 'days') : null, 'oldest waiting');

    const waiting = this.sect(body, 'WAITING', active.length
      ? 'The inbox empties. Ask Larry to process what is here.'
      : null);
    this.fileRows(waiting, this.recent(active, 8), { empty: 'the inbox is empty — as it should be' });

    const arch = this.sect(body, 'RECENTLY ARCHIVED');
    this.fileRows(arch, this.recent(archived, 5), { empty: 'processed captures will land here' });
  }

  /* ----------------------------------------------------- 03 inner world -- */

  renderInner(body) {
    const journal = this.notes('Journal');
    const now = new Date();
    const monthPrefix = this.room + '/Journal/' + now.getFullYear() + '/' + String(now.getMonth() + 1).padStart(2, '0') + '/';
    const thisMonth = journal.filter((f) => f.path.startsWith(monthPrefix));
    const goals = this.notes('My Life/Goals');
    const achieved = goals.filter((f) => this.fm(f).status === 'achieved');
    const projects = this.notes('My Life/Projects');
    const activeProjects = projects.filter((f) => this.fm(f).status === 'active');
    const people = this.notes('Contacts/People');
    const companies = this.notes('Contacts/Companies');
    const reflections = this.notes('ICOR Journey Notes');

    const band = this.slabBand(body);
    this.slab(band, journal.length, null, 'journal entries');
    this.slab(band, thisMonth.length, null, 'entries this month', thisMonth.length > 0);
    this.slab(band, achieved.length, '/ ' + goals.length, 'goals achieved');
    this.slab(band, activeProjects.length, '/ ' + projects.length, 'projects active');
    this.slab(band, people.length + companies.length, null, 'contacts');
    this.slab(band, reflections.length, null, 'myicor reflections');

    const gsec = this.sect(body, 'GOALS');
    if (!goals.length) {
      gsec.createDiv({ cls: 'micor-hand-note', text: 'no goals yet — every project needs one' });
    } else {
      const list = gsec.createDiv({ cls: 'micor-gap-list' });
      for (const g of goals) {
        const done = this.fm(g).status === 'achieved';
        const row = list.createDiv({ cls: 'micor-hit is-clickable micor-room-row' });
        const k = row.createDiv({ cls: 'micor-hit-kicker' });
        k.createSpan({ cls: done ? 'micor-kicker-ok' : '', text: done ? 'ACHIEVED' : 'NOT ACHIEVED' });
        const linked = projects.filter((f) => {
          const goal = this.fm(f).goal;
          return goal && String(goal).includes(g.basename);
        });
        if (linked.length) k.createSpan({ text: ' · ' + linked.length + ' PROJECT' + (linked.length === 1 ? '' : 'S') });
        row.createDiv({ cls: 'micor-hit-title', text: g.basename });
        row.addEventListener('click', () => this.openFile(g));
      }
    }

    const psec = this.sect(body, 'ACTIVE PROJECTS');
    this.fileRows(psec, activeProjects, {
      empty: 'no active projects',
      kicker: (f) => {
        const m = this.fm(f);
        const parts = ['ACTIVE'];
        if (m.start_date) parts.push('SINCE ' + kickerDate(m.start_date));
        return parts.join(' · ');
      },
    });

    const latest = this.sect(body, 'LATEST INK');
    this.fileRows(latest, this.recent(this.notes(), 6));
  }

  /* ---------------------------------------------------------- 04 assets -- */

  renderAssets(body) {
    const images = this.files('Images');
    const audio = this.files('Audio');
    const docs = this.files('Documents');
    const allFiles = this.files().filter((f) => f.name !== 'README.md');
    const totalBytes = allFiles.reduce((a, f) => a + (f.stat.size || 0), 0);
    const mb = totalBytes / 1048576;
    const sizeText = mb >= 1024 ? (mb / 1024).toFixed(1) : mb >= 10 ? Math.round(mb) : mb.toFixed(1);

    const band = this.slabBand(body);
    this.slab(band, images.length, null, 'images');
    this.slab(band, audio.length, null, 'audio files');
    this.slab(band, docs.length, null, 'documents');
    this.slab(band, sizeText, mb >= 1024 ? 'GB' : 'MB', 'on the shelves');

    const latest = this.sect(body, 'LATEST ARRIVALS');
    this.fileRows(latest, this.recent(allFiles, 8), {
      empty: 'attachments land here automatically',
      kicker: (f) => {
        const rel = f.path.slice(this.room.length + 1);
        const folder = rel.includes('/') ? rel.slice(0, rel.indexOf('/')).toUpperCase() : 'ASSETS';
        const kb = (f.stat.size || 0) / 1024;
        const size = kb >= 1024 ? (kb / 1024).toFixed(1) + ' MB' : Math.max(1, Math.round(kb)) + ' KB';
        return folder + ' · ' + size + ' · ' + this.ageText(f.stat.mtime);
      },
      title: (f) => f.name,
    });

    const largest = this.sect(body, 'HEAVIEST FILES');
    const big = [...allFiles].sort((a, b) => (b.stat.size || 0) - (a.stat.size || 0)).slice(0, 5);
    this.fileRows(largest, big, {
      empty: 'nothing heavy yet',
      kicker: (f) => {
        const kb = (f.stat.size || 0) / 1024;
        return kb >= 1024 ? (kb / 1024).toFixed(1) + ' MB' : Math.max(1, Math.round(kb)) + ' KB';
      },
      title: (f) => f.name,
    });
  }

  /* ----------------------------------------------------- 06 outer world -- */

  /* One note per thing someone else made (`type: source`), from the Web
   * Clipper, Readwise or by hand. The fields are the vault schema's:
   * source_type, author, consumed, captured, and the links that give a
   * source its place (projects, key_elements, topics). */
  renderOuter(body) {
    const notes = this.notes();
    const sources = notes.filter((f) => this.fm(f).type === 'source');
    const unread = sources.filter((f) => outerUnread(this.fm(f)));
    const unlinked = sources.filter((f) => !outerLinked(this.fm(f)));
    const now = new Date();
    const thisMonth = sources.filter((f) => {
      const c = this.fm(f).captured;
      const d = c ? new Date(String(c)) : new Date(f.stat.ctime || f.stat.mtime);
      return !isNaN(d) && d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();
    });
    const kicker = (f) => {
      const m = this.fm(f);
      const parts = [String(m.source_type || 'source').toUpperCase()];
      if (m.author) parts.push(String(m.author).replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1').toUpperCase());
      parts.push(this.ageText(f.stat.mtime));
      return parts.join(' · ');
    };

    const band = this.slabBand(body);
    this.slab(band, sources.length, null, 'sources');
    this.slab(band, unread.length, null, 'in the reading queue', unread.length > 0);
    this.slab(band, thisMonth.length, null, 'captured this month');
    this.slab(band, sources.length - unlinked.length, '/ ' + sources.length, 'linked to what they serve');

    const qsec = this.sect(body, 'THE READING QUEUE');
    this.fileRows(qsec, this.recent(unread, 8), { empty: 'nothing waiting to be read', kicker });

    const usec = this.sect(body, 'NOT CONNECTED YET', unlinked.length
      ? 'A source earns its place by linking to a project, a Key Element or a topic.'
      : null);
    this.fileRows(usec, this.recent(unlinked, 5), { empty: 'every source links to what it serves', kicker });

    const latest = this.sect(body, 'LATEST ARRIVALS');
    this.fileRows(latest, this.recent(sources.length ? sources : notes, 6), {
      empty: 'clips from the Web Clipper and highlights from Readwise land here',
      kicker,
    });
  }
}

module.exports = MyicorConnectPlugin;
